(function(root,factory){const fn=factory();if(typeof module==='object'&&module.exports)module.exports=fn;else root.WorksheetScienceOtherGrades=fn;})(globalThis,()=>{'use strict';
const LESSONS=[[3,1,"힘과 우리 생활","물체를 미는 모습과 당기는 모습을 찾아볼까요",[["장난감 상자","손으로 상자를 앞으로 밀었다.","상자가 손에서 멀어지는 쪽으로 움직였다.","미는 힘은 물체의 운동을 변화시킬 수 있다.","가해진 힘의 정확한 크기","같은 상자에 미는 방향을 바꿔 본다."],["손잡이 달린 서랍","서랍 손잡이를 몸 쪽으로 당겼다.","서랍이 사람 가까이로 열렸다.","당기는 힘은 물체를 가까운 쪽으로 움직이게 할 수 있다.","서랍 안 물건의 총 질량","손잡이를 잡아당기는 방향을 살핀다."],["문 밀어 열기","문 손잡이 부근을 바깥으로 밀었다.","문이 경첩을 중심으로 돌아 열렸다.","미는 힘은 물체를 회전시키기도 한다.","문에 작용한 힘의 수치","미는 위치에 따른 열림을 비교한다."],["썰매 끌기","줄을 잡아 썰매를 앞쪽으로 당겼다.","썰매가 줄을 당긴 방향으로 미끄러졌다.","줄을 통해 물체에 당기는 힘을 전달할 수 있다.","썰매와 땅 사이 마찰력 크기","줄의 방향을 바꿔 움직임을 본다."],["공 밀기","탁자 위 정지한 공을 손끝으로 밀었다.","공이 굴러가기 시작했다.","정지한 물체도 힘을 받으면 움직일 수 있다.","공의 정확한 운동 속력","미는 힘을 달리해 이동 거리를 잰다."]]],[3,1,"힘과 우리 생활","물체를 밀거나 당겨 볼까요",[["양쪽에서 밀기","장난감 차를 오른쪽에서 왼쪽으로 밀었다.","차가 왼쪽으로 이동했다.","힘이 작용하는 방향이 움직임에 영향을 준다.","차가 받은 총 힘의 크기","반대 방향으로 밀어 이동을 비교한다."],["카트 당기기","손잡이가 있는 작은 수레를 뒤쪽으로 당겼다.","수레가 손잡이 쪽으로 움직였다.","당기는 힘은 물체의 위치를 변화시킨다.","바퀴의 회전수","줄과 손잡이로 당길 때를 비교한다."],["점토 누르기","부드러운 점토를 양손으로 눌렀다.","점토의 납작한 모양이 달라졌다.","힘은 물체를 움직이거나 모양을 바꿀 수 있다.","점토의 정확한 밀도","누르는 힘을 달리해 모양을 비교한다."],["탄력 공","말랑한 공을 손으로 쥐었다가 놓았다.","공이 눌렸다가 대부분 원래 모양으로 돌아왔다.","물체의 재료는 힘을 받은 뒤 모양 변화에 영향을 준다.","재료의 탄성 계수","같은 힘으로 다른 재료 공을 쥐어 본다."],["닫힌 문","닫힌 문을 경첩 쪽 가까이에서 밀었다.","문이 조금 움직이거나 잘 열리지 않았다.","힘을 가하는 위치도 회전에 영향을 줄 수 있다.","문 손잡이까지 정확한 거리","손잡이 쪽에서 미는 경우와 비교한다."]]],[3,1,"힘과 우리 생활","무거운 물체와 가벼운 물체를 밀거나 당겨 볼까요",[["같은 수레 두 종류","같은 바닥에서 빈 수레와 책을 싣고 무거워진 수레를 비슷한 힘으로 밀었다.","책을 실은 수레의 움직임이 더 작았다.","같은 조건에서는 질량이 움직임 변화를 다르게 만든다.","바퀴에 생긴 정확한 마찰력","수레 무게만 바꾼 반복 실험을 한다."],["빈 상자와 채운 상자","같은 재질 상자에 물건을 넣어 무게를 늘렸다.","채운 상자를 끌 때 더 큰 힘이 필요한 듯 느껴졌다.","물체의 무게는 밀고 당기는 데 영향을 줄 수 있다.","손으로 가한 힘의 정확한 수치","힘 측정 도구로 두 상자를 당겨 본다."],["장난감 자동차","같은 자동차에 추를 추가하고 같은 바닥에서 짧게 밀었다.","추를 얹었을 때 이동 양상이 달랐다.","질량 외의 조건은 같게 하는 것이 중요하다.","실제 최고 속력","밀어 주는 시간과 힘을 일정하게 해 본다."],["같은 경사로","높이가 같은 빗면에 질량이 다른 같은 모양의 수레를 올렸다.","두 수레의 운동을 비교할 수 있었다.","운동 비교에서는 경사와 바퀴 조건을 맞춰야 한다.","두 수레의 마찰력 수치","바퀴 상태가 같은 수레로 반복한다."],["밀기보다 당기기","같은 상자를 밀거나 당기되 바닥과 힘 방향이 달라졌다.","두 방법에서 움직이기 쉬운 정도가 다를 수 있었다.","힘의 방향과 바닥 상태도 운동에 영향을 준다.","질량만이 차이를 만들었는지","밀기와 당기기의 힘 방향을 맞춰 비교한다."]]],[3,1,"힘과 우리 생활","수평 잡기 활동으로 물체의 무게를 비교해 볼까요",[["양팔저울과 구슬","양팔저울 양쪽에 서로 다른 구슬을 하나씩 놓았다.","가 구슬 쪽 접시가 아래로 내려갔다.","같은 조건에서는 아래쪽이 더 무거운 물체일 수 있다.","구슬의 정확한 질량 차이","각 구슬의 무게를 눈금 저울로 확인한다."],["같은 높이 접시","양팔저울에 똑같은 추를 각각 하나씩 놓았다.","두 접시의 높이가 같아졌다.","양쪽이 균형을 이루면 무게가 같을 수 있다.","추가 만들어진 금속 종류","추 수를 하나씩 바꿔 균형을 관찰한다."],["막대 수평대","막대 양쪽에서 받침점과 같은 거리에 물체를 놓았다.","무거운 쪽이 아래로 기울었다.","같은 거리일 때 무게 차이가 균형에 영향을 준다.","각 물체의 부피","양쪽 물체를 바꿔 놓아 결과를 확인한다."],["거리 다른 추","수평 막대의 한쪽 추를 받침점에서 더 멀리 옮겼다.","같은 추가 놓여도 막대의 기울기가 달라졌다.","무게뿐 아니라 받침점에서의 거리도 수평에 영향을 준다.","정확한 회전력 값","추의 거리를 눈금으로 조절해 본다."],["다른 물체 더하기","수평을 이룬 양팔저울 한쪽에 작은 추를 추가했다.","추를 더한 쪽이 아래로 내려갔다.","추가된 물체의 무게가 양쪽의 균형을 깨뜨린다.","추의 정확한 재질","반대편에 추를 하나씩 더하며 비교한다."]]],[3,1,"힘과 우리 생활","저울이 필요한 까닭은 무엇일까요",[["손으로 들기","크기가 비슷한 두 돌을 손으로 들어 보았다.","손의 느낌만으로 무게 차이를 확실히 말하기 어려웠다.","저울을 사용하면 느낌 대신 수치로 무게를 비교할 수 있다.","두 돌의 실제 질량","저울로 각각 무게를 재어 기록한다."],["과일 가게","과일 두 봉지의 무게를 저울로 재었다.","가 봉지는 800 g, 나 봉지는 600 g으로 표시됐다.","같은 단위를 쓰면 무게를 객관적으로 비교할 수 있다.","과일의 총 개수","과일 종류와 무게를 표로 기록한다."],["우편 소포","소포의 무게를 저울로 확인한 뒤 요금 구간을 살폈다.","무게 기준에 따라 예상 요금이 달라질 수 있었다.","무게 측정은 배송 등 생활 활동에 필요하다.","소포의 실제 배송 거리","저울 표시와 요금표를 함께 확인한다."],["요리 재료","요리법에 밀가루 200 g이 필요하다고 써 있었다.","저울을 사용해 정해진 만큼의 재료를 준비했다.","정량 측정은 같은 요리 결과를 내는 데 도움을 준다.","밀가루의 습도","재료 양을 달리한 결과를 기록한다."],["눈짐작 비교","크기는 크지만 가벼운 스펀지와 작은 쇠붙이를 비교했다.","큰 스펀지가 반드시 더 무겁지는 않았다.","크기만으로 무게를 정확히 알 수 없다.","두 물체의 실제 밀도","각 물체를 같은 저울로 재어 본다."]]],[3,1,"힘과 우리 생활","저울로 물체의 무게를 비교해 볼까요",[["전자저울의 사과","전자저울에 사과 한 개를 올렸다.","표시창에 210 g이 나타났다.","저울은 물체의 무게를 일정한 단위로 나타낸다.","사과의 씨앗 개수","같은 저울에서 다른 사과도 재어 본다."],["영점 맞추기","저울의 표시가 0이 아닌 채로 시작해 빈 접시 상태에서 0으로 조정했다.","영점을 조절한 뒤 물체를 재었다.","영점 조절은 측정 오류를 줄일 수 있다.","저울의 내부 회로","영점 조절 전후 같은 물체를 재어 비교한다."],["컵 빼고 재기","빈 컵을 저울에 올리고 영점을 맞춘 뒤 콩을 담았다.","컵 무게를 빼고 콩만의 값이 표시됐다.","용기 무게를 제외하는 영점 기능을 이용했다.","컵에 담긴 콩알의 정확한 수","콩을 한 숟갈씩 추가하며 무게를 기록한다."],["단위 확인","가 물체는 350 g, 나 물체는 0.5 kg으로 기록됐다.","0.5 kg을 500 g으로 바꾸어 나가 더 무겁다고 판단했다.","다른 단위는 같게 바꿔 비교한다.","두 물체의 재료 종류","같은 단위로 변환한 기록을 비교한다."],["반복 측정","같은 고무공을 같은 저울에 세 번 올렸더니 80 g, 81 g, 80 g이었다.","측정값에 작은 차이가 있었다.","측정에는 도구와 놓는 방법에 따른 오차가 생길 수 있다.","공의 정확한 부피","놓는 위치를 같게 해 반복 측정한다."]]],[3,1,"힘과 우리 생활","지레와 빗면을 알아볼까요",[["받침점 있는 막대","긴 막대 아래 받침점을 놓고 한쪽을 눌렀다.","반대쪽에 있는 물체가 들어 올려졌다.","지레는 받침점을 중심으로 물체를 들어 올리는 데 이용된다.","누르는 힘의 정확한 크기","받침점 위치를 바꿔 들어 올려 본다."],["계단과 경사로","같은 높이의 무거운 상자를 계단 대신 완만한 경사로로 올렸다.","경사로에서는 긴 거리를 따라 천천히 움직였다.","빗면은 이동 거리를 늘려 필요한 힘을 줄이는 데 도움 될 수 있다.","이동할 때의 정확한 일의 양","빗면 기울기를 바꾸어 힘을 측정한다."],["병따개","받침점을 이용하는 병따개로 병뚜껑을 열었다.","손으로 직접 떼기 어려운 뚜껑이 들렸다.","생활 도구에 지레의 원리가 쓰인다.","병뚜껑의 정확한 질량","손잡이 길이를 바꾸어 필요한 힘을 비교한다."],["짐 옮기는 널판","높이가 있는 차에 짐을 올릴 때 널판을 비스듬히 놓았다.","짐을 위로 수직으로 드는 대신 판을 따라 밀었다.","경사로는 짐을 높은 곳까지 이동시키는 방법이 된다.","널판의 실제 마찰계수","기울기가 다른 널판에서 필요한 힘을 측정한다."],["가위와 받침점","가위 손잡이를 움직이자 중간의 축을 기준으로 날이 움직였다.","손잡이 움직임이 날의 잘라내는 동작으로 이어졌다.","가위에도 받침점을 중심으로 하는 지레 작용이 있다.","날 끝에서 생기는 정확한 힘","받침점에 가까운 곳과 먼 곳에서 종이를 잘라 본다."]]],[3,1,"동물의 생활","우리 주변에는 어떤 동물이 있을까요",[["학교 화단의 개미","날이 따뜻한 오후 학교 화단에서 개미를 관찰했다.","개미 여러 마리가 흙 위를 이동했다.","작은 동물도 생활 공간에서 관찰할 수 있다.","화단 전체 개미 수","시간을 바꿔 개미 활동을 기록한다."],["나무의 참새","나무 가지 가까운 곳에서 참새를 관찰했다.","참새가 나뭇가지에 앉았다가 날아갔다.","주변 나무도 새가 이용하는 생활 공간이다.","참새가 하루 동안 이동한 거리","먹이 활동을 방해하지 않고 멀리서 살핀다."],["돌 밑 지렁이","비가 온 뒤 젖은 흙에서 지렁이를 발견했다.","지렁이가 흙 속으로 천천히 이동했다.","동물마다 생활에 적합한 환경이 다르다.","지렁이의 정확한 수명","습한 흙과 마른 흙에서 관찰된 장소를 비교한다."],["연못의 물고기","연못 물속에서 작은 물고기를 발견했다.","물고기가 지느러미를 움직여 헤엄쳤다.","물속 동물은 물에서 움직일 수 있는 몸 구조가 있다.","한 시간 동안 헤엄친 거리","지느러미의 움직임을 영상 없이 눈으로 살핀다."],["담장 위 달팽이","비가 지난 뒤 축축한 담장에서 달팽이를 관찰했다.","달팽이가 천천히 기어가며 흔적을 남겼다.","동물은 움직이는 모습과 몸의 특징이 다양하다.","달팽이가 이동한 전체 길이","촉각과 이동 모습을 건드리지 않고 관찰한다."]]],[3,1,"동물의 생활","여러 가지 동물을 관찰하고 분류해 볼까요",[["다리 수 비교","개미와 거미의 다리 수를 그림과 실물 자료에서 비교했다.","개미는 다리가 여섯 개이고 거미는 여덟 개였다.","동물은 관찰할 수 있는 공통점과 차이점으로 분류한다.","각 개체의 정확한 몸무게","다리 수가 다른 동물의 자료도 모은다."],["날개 유무","나비와 지렁이의 겉모습을 비교했다.","나비에는 날개가 있지만 지렁이에는 없다.","날개의 유무를 분류 기준으로 사용할 수 있다.","나비의 정확한 날갯짓 횟수","다른 동물도 날개 유무를 살펴 분류한다."],["물과 육지","붕어와 참새가 생활하는 장소를 각각 관찰했다.","붕어는 물속에, 참새는 나무와 땅 위에 있었다.","주된 서식 환경을 기준으로 동물을 나눌 수 있다.","개체별 먹이 섭취량","동물이 사는 장소를 여러 날 관찰한다."],["등뼈 비교","고양이와 달팽이의 몸 구조를 자료에서 비교했다.","고양이는 등뼈가 있고 달팽이는 등뼈가 없다.","등뼈 유무는 동물 분류의 중요한 특징이다.","고양이의 실제 나이","등뼈가 다른 동물 사례도 찾아본다."],["움직이는 방법","뱀과 개구리의 이동 모습을 비교했다.","뱀은 몸을 굽혀 기고 개구리는 주로 뛰거나 헤엄쳤다.","이동 방식은 몸 구조 및 생활환경과 관련된다.","두 동물의 최대 속력","환경에 따른 이동 방식도 조사한다."]]],[3,1,"동물의 생활","땅에서 사는 동물을 알아볼까요",[["토끼의 뒷다리","들판에 사는 토끼의 다리 모습을 살펴봤다.","뒷다리가 길고 뛰어서 이동했다.","동물의 다리 구조는 이동 방식과 관련된다.","토끼가 하루 먹는 풀의 양","뛰는 모습과 다리 움직임을 비교한다."],["두더지의 앞발","땅속에서 생활하는 두더지의 앞발 모형을 살폈다.","넓은 앞발에 흙을 파기 좋은 발톱이 있었다.","땅을 파는 몸 특징은 서식 환경과 관련된다.","두더지의 굴 전체 길이","땅을 파는 동물의 앞발도 비교한다."],["사막 도마뱀","건조한 땅에서 사는 도마뱀의 몸 모습을 자료로 보았다.","피부 표면에 비늘이 있었고 땅 위로 이동했다.","몸을 보호하는 특징이 생활환경과 연관된다.","이 개체의 정확한 체온","다른 사막 동물의 겉모습을 조사한다."],["나무를 오르는 다람쥐","숲속 나무에서 다람쥐를 멀리서 관찰했다.","발톱으로 나무껍질을 붙잡고 위로 올라갔다.","발톱과 발의 구조는 나무를 오르는 데 도움이 된다.","한 번에 올라간 최대 높이","오르는 방향에 따른 발의 움직임을 살핀다."],["흙속의 지렁이","화단 흙을 관찰하며 지렁이 이동을 살폈다.","다리 없이 몸을 늘이고 줄이며 앞으로 이동했다.","몸의 움직임이 흙속 이동에 알맞다.","이 지렁이의 정확한 길이 변화","젖은 흙과 마른 흙에서 이동을 비교한다."]]],[3,1,"동물의 생활","물에서 사는 동물을 알아볼까요",[["붕어의 지느러미","연못에서 붕어가 수영하는 모습을 살펴봤다.","지느러미를 움직이며 방향을 바꿨다.","지느러미는 물속 이동과 방향 조절에 도움이 된다.","지느러미가 낸 정확한 힘","지느러미의 각 부분 움직임을 관찰한다."],["돌고래의 호흡","돌고래가 물 위로 올라오는 영상 자료를 보았다.","수면에서 숨을 쉬었다.","포유류인 돌고래는 폐로 공기를 호흡한다.","한 번에 들이마신 공기량","잠수 전후 수면에 나오는 시간을 살핀다."],["오징어의 움직임","물속 오징어의 움직임을 기록한 자료를 보았다.","몸에서 물을 내보내며 빠르게 이동했다.","물 분출도 물속 동물의 이동 방법이다.","오징어가 분출한 물의 질량","지느러미 이동과 분출 이동을 비교한다."],["게의 다리","해안 얕은 물과 갯벌에서 게를 관찰했다.","여러 다리로 바닥을 걸어 이동했다.","물속과 갯벌 동물도 걷는 구조를 사용할 수 있다.","게가 하루 걸은 거리","물에서와 갯벌에서 걷는 모습을 비교한다."],["해파리의 움직임","바닷속 해파리의 움직임을 살펴봤다.","몸을 수축하고 펴며 물속을 움직였다.","같은 물환경에서도 이동에 쓰는 구조가 다르다.","이 해파리의 정확한 이동 속력","해파리와 물고기의 이동 방식을 비교한다."]]],[3,1,"동물의 생활","일상생활에서 동물의 특징을 어떻게 이용할까요",[["오리발 수영","물새의 물갈퀴를 관찰하고 수영용 오리발과 비교했다.","넓은 오리발을 이용하면 물을 더 밀 수 있었다.","물갈퀴 구조에서 생활 도구의 생각을 얻었다.","수영 속력이 몇 배 증가하는지","오리발 사용 전후 같은 거리 시간을 비교한다."],["고양이 발과 소리","고양이가 발바닥의 부드러운 부분으로 조용히 걷는 모습을 살펴봤다.","발을 디딜 때 소음이 비교적 작았다.","부드러운 접촉면은 충격과 소리를 줄이는 데 도움 된다.","실제 소음 데시벨 값","바닥 재질별 걷는 소리를 측정한다."],["벌집 모양","벌집의 육각형 칸들을 확대해 관찰했다.","육각형이 빈틈 없이 나란히 반복됐다.","규칙적 모양은 공간을 구분하는 구조의 참고가 된다.","한 벌집에 쓰인 밀랍의 총량","같은 넓이에서 도형별 배치를 비교한다."],["물총새와 열차","물총새 부리의 길쭉한 모양을 빠른 열차 앞부분 사진과 비교했다.","두 모양이 앞이 좁고 뒤가 넓게 이어졌다.","자연의 모양은 물체 디자인에 아이디어를 준다.","정확한 공기 저항 변화","앞부분 모양별 공기 흐름을 모형으로 비교한다."],["도마뱀붙이 발","도마뱀붙이가 벽을 타고 오르는 모습을 관찰했다.","발끝이 벽에 붙어 몸을 지탱했다.","접착 구조를 생활용품 개발에 참고할 수 있다.","이 발끝의 정확한 접착력","표면 재질에 따른 붙는 정도를 비교한다."]]],[3,1,"식물의 생활","우리 주변에는 어떤 식물이 살고 있을까요",[["학교 화단","학교 화단의 풀과 작은 꽃을 관찰했다.","잎과 줄기 모양이 다른 식물들이 함께 자라고 있었다.","가까운 생활 공간에도 다양한 식물이 산다.","화단의 전체 식물 종 수","식물별 잎·줄기 특징을 사진 없이 기록한다."],["가로수","길을 따라 심어진 나무를 관찰했다.","큰 줄기와 가지, 여러 잎이 있었다.","나무는 땅 위에서 줄기와 잎을 발달시킨다.","나무의 정확한 나이","계절별 잎의 변화를 관찰한다."],["잔디 운동장","운동장 가장자리 잔디와 민들레를 살폈다.","잔디의 잎은 가늘고 민들레 잎은 넓었다.","식물마다 잎의 모양이 다르다.","각 식물의 뿌리 길이","잎의 크기와 모양을 비교 기록한다."],["연못가 갈대","연못 가장자리에서 키 큰 갈대를 발견했다.","가늘고 긴 잎이 바람에 흔들렸다.","습한 장소에서도 식물이 자랄 수 있다.","갈대 한 포기의 정확한 질량","연못가와 마른 땅의 식물을 비교한다."],["화분의 콩","교실 창가 화분에서 자란 콩 식물을 살펴봤다.","줄기에서 잎이 나오고 위쪽으로 자랐다.","식물은 잎·줄기·뿌리 같은 구조를 갖는다.","화분 속 뿌리의 전체 길이","날짜별 키와 잎 수를 기록한다."]]],[3,1,"식물의 생활","잎의 생김새에 따라 식물을 분류해 볼까요",[["소나무와 은행나무","소나무 잎과 은행나무 잎 모양을 살펴봤다.","소나무는 가늘고 길고 은행나무는 부채 모양이었다.","잎 모양은 식물을 나누는 관찰 기준이 된다.","두 식물의 정확한 잎 질량","잎 가장자리와 잎맥도 비교한다."],["단풍나무와 대나무","단풍나무와 대나무의 잎을 사진 자료로 비교했다.","단풍나무는 손바닥처럼 갈라지고 대나무는 길쭉했다.","식물별로 잎의 전체 윤곽이 다르다.","각 나무의 높이","잎 길이와 폭을 같은 방법으로 잰다."],["잎맥 관찰","강낭콩 잎과 벼 잎의 잎맥을 살폈다.","강낭콩에는 그물 모양 잎맥, 벼에는 나란한 잎맥이 보였다.","잎맥의 배열도 분류에 사용할 수 있다.","각 식물의 꽃 색깔","같은 잎맥을 가진 다른 식물을 찾는다."],["잎 끝의 모양","두 식물의 잎 끝을 확대경으로 살폈다.","가 잎 끝은 뾰족하고 나 잎 끝은 둥글었다.","작은 모양 차이도 분류 기준이 될 수 있다.","두 식물의 서식지 전체","잎 끝의 모양을 여러 개체에서 비교한다."],["잎 크기의 차이","같은 장소에서 고무나무 잎과 잔디 잎을 비교했다.","고무나무 잎은 넓고 잔디 잎은 가늘었다.","잎의 넓이와 길이는 관찰 가능한 특징이다.","각 잎의 광합성 속도","잎을 종이에 대고 크기를 비교한다."]]],[3,1,"식물의 생활","들과 산에서 사는 식물을 알아볼까요",[["들판의 민들레","햇빛이 잘 드는 들판에서 민들레를 관찰했다.","낮은 줄기 주변으로 잎이 퍼져 자랐다.","들판에는 햇빛을 이용하는 여러 풀이 산다.","한 포기의 실제 뿌리 길이","같은 들판의 다른 풀과 잎을 비교한다."],["숲속의 소나무","산의 비탈에서 소나무를 관찰했다.","곧은 줄기와 가느다란 잎이 있었다.","산에는 다양한 나무가 환경에 적응해 산다.","이 소나무의 정확한 수령","솔잎과 다른 나무 잎을 비교한다."],["숲 바닥의 이끼","그늘지고 습한 바위에서 이끼가 자랐다.","이끼가 낮고 촘촘히 퍼져 있었다.","그늘과 수분 조건이 이끼 생장에 영향을 준다.","그 바위의 실제 수분 함량","그늘과 햇볕 장소의 이끼 분포를 조사한다."],["산의 낙엽","가을 산에서 넓은 잎의 나무들이 잎을 떨어뜨렸다.","땅 위에 낙엽이 쌓였다.","일부 나무는 계절에 따라 잎을 떨어뜨린다.","낙엽 한 장의 정확한 질량","봄과 가을 같은 나무 잎을 비교한다."],["풀과 나무 비교","산길에서 키 낮은 풀과 큰 나무를 나란히 관찰했다.","두 식물의 줄기 굵기와 키가 달랐다.","자라는 모습과 줄기의 성질로 식물을 비교할 수 있다.","나무 뿌리의 깊이","줄기의 굵기와 높이를 재어 본다."]]],[3,1,"식물의 생활","사막에서 사는 식물을 알아볼까요",[["선인장의 줄기","사막 식물인 선인장의 몸을 관찰했다.","두꺼운 줄기와 가시가 보였다.","줄기에 물을 저장하고 잎이 변형된 가시로 물 손실을 줄일 수 있다.","줄기 속에 저장된 물의 정확한 양","보통 잎이 있는 식물과 표면을 비교한다."],["비가 적은 땅","오랫동안 비가 적은 사막의 식물 사진을 살폈다.","식물 사이가 멀고 주변이 건조했다.","물 부족은 사막 생물이 겪는 중요한 조건이다.","지역의 연간 정확한 강수량","강수량과 식물 분포 지도를 함께 본다."],["깊은 뿌리","뿌리를 깊게 내리는 사막 식물의 단면 모형을 보았다.","뿌리가 지표보다 깊은 곳까지 뻗어 있었다.","뿌리 구조는 물을 얻는 데 도움이 될 수 있다.","실제 흡수한 물의 양","다른 건조지역 식물 뿌리도 조사한다."],["넓게 퍼진 뿌리","어떤 사막 식물은 땅 가까이 넓게 뿌리를 퍼뜨렸다.","뿌리가 얕은 흙 여러 방향으로 이어졌다.","짧게 오는 비를 넓은 범위에서 흡수하는 데 도움이 될 수 있다.","뿌리 끝의 정확한 총길이","비 뒤에 뿌리 주변의 흙 수분을 관찰한다."],["건조한 낮","강한 햇빛 아래에서 일부 사막 식물은 물 손실을 줄이는 표면을 가진다.","잎이 작거나 두꺼운 표면이 관찰됐다.","식물의 겉모습은 물을 아끼는 방식과 관련된다.","그 식물의 실제 증산량","잎 면적이 다른 식물을 비교한다."]]],[3,1,"식물의 생활","연못이나 강에서 사는 식물을 알아볼까요",[["연잎의 표면","연못에 뜬 연잎 표면에 물방울을 떨어뜨렸다.","물방울이 퍼지지 않고 동글게 맺혔다.","연잎의 표면 구조는 물이 잘 젖지 않게 한다.","연잎의 정확한 표면장력","다른 잎에도 같은 물방울을 떨어뜨려 비교한다."],["부레옥잠의 잎자루","부레옥잠 잎자루를 잘라 만든 단면 자료를 살폈다.","부풀어 있는 부분에 공기 공간이 많았다.","공기 공간은 물 위에 떠 있는 데 도움을 준다.","잎자루 안의 정확한 공기 부피","물에 띄운 잎자루의 부력을 비교한다."],["검정말의 잎","수중 식물 검정말이 물속에서 자라는 모습을 봤다.","가늘고 작은 잎이 물속 줄기에 붙어 있었다.","식물 가운데는 물속에서 살아가는 종류가 있다.","잎의 실제 광합성량","빛 조건에 따른 기포 발생을 관찰한다."],["갈대의 줄기","하천 가장자리 갈대가 서 있는 모습을 봤다.","길고 단단한 줄기가 물가에서 위로 자랐다.","습한 가장자리에서도 줄기를 세워 생장하는 식물이 있다.","한 포기의 전체 뿌리 면적","수위에 따라 자라는 위치를 조사한다."],["수면의 개구리밥","잔잔한 연못 수면에 개구리밥이 떠 있었다.","아주 작은 잎처럼 보이는 몸이 여러 개 모여 있었다.","일부 식물은 물 위에 떠서 생활한다.","개구리밥 전체 개체 수","수면에 뜨는 위치를 여러 날 기록한다."]]],[3,1,"식물의 생활","식물의 특징을 이용한 생활용품에는 어떤 것이 있을까요",[["연잎과 방수","연잎의 물방울이 맺히는 모습을 생활 방수 표면과 비교했다.","연잎 위에서 물방울이 쉽게 굴러갔다.","표면에 물이 잘 퍼지지 않는 특징을 도구 제작에 참고한다.","방수 소재의 정확한 내구성","잎과 소재에 같은 양의 물을 떨어뜨려 비교한다."],["우엉 열매의 갈고리","우엉 열매가 옷감에 달라붙은 모습을 확대했다.","열매 표면의 작은 갈고리가 섬유에 걸렸다.","갈고리 구조는 찍찍이 접착 방식의 아이디어다.","열매 하나가 버티는 최대 힘","열매와 찍찍이의 붙는 원리를 비교한다."],["대나무로 만든 바구니","대나무 줄기를 가늘게 쪼개 엮은 바구니를 살폈다.","긴 대나무 조각들이 휘어지며 바구니 모양을 이뤘다.","줄기의 길이와 유연성을 생활용품에 이용할 수 있다.","바구니의 최대 하중","대나무와 플라스틱 조각의 휘어짐을 비교한다."],["목화 솜","목화에서 얻은 솜으로 만든 천을 살펴봤다.","솜의 섬유가 부드럽게 얽혀 있었다.","식물의 섬유는 옷과 천의 재료가 된다.","이 천에 든 섬유 총가닥 수","서로 다른 섬유의 촉감을 비교한다."],["나무의 목재","나무로 만든 책상과 의자를 살펴봤다.","단단한 목재가 몸체와 다리를 이루었다.","줄기의 단단한 성질을 가구 재료로 이용한다.","이 가구의 정확한 제조 연도","나무와 금속 의자의 재료 특징을 비교한다."]]],[3,1,"생물의 한살이","배추흰나비 알을 관찰해 볼까요",[["잎 뒷면의 알","배추 잎 뒷면에서 작은 알을 확대경으로 관찰했다.","작은 알들이 잎 표면에 붙어 있었다.","배추흰나비 한살이는 알에서 시작한다.","알의 정확한 무게","알의 위치와 모양을 날짜별로 기록한다."],["알의 색 변화","며칠 동안 같은 알을 멀리서 관찰했다.","알의 색이 처음과 조금 다르게 보였다.","알 속에서 발생이 진행되면 겉모습도 바뀔 수 있다.","알 안 애벌레의 실제 길이","같은 조명에서 알 색을 반복 관찰한다."],["알 낳는 장소","배추흰나비가 배추 잎 주변에 머물다 알을 낳은 기록을 보았다.","알이 배추 잎에 붙어 있었다.","먹이식물 가까이에 알을 낳는 것은 애벌레 생존과 관련된다.","어른벌레의 알 낳는 횟수","잎 위치에 따른 알 수를 비교한다."],["확대경 사용","작은 알을 손으로 만지지 않고 확대경으로 살폈다.","맨눈보다 알의 모양이 자세히 보였다.","작은 생물의 특징은 관찰 도구로 살필 수 있다.","알 껍질의 실제 두께","여러 배율에서 보이는 모양을 기록한다."],["알 보호","관찰 중 알이 붙은 잎을 세게 흔들지 않았다.","알은 잎에 그대로 붙어 있었다.","한살이 관찰에는 생물의 생장을 방해하지 않는 태도가 필요하다.","알의 부화 예정 시각","알을 두고 일정한 시간에 관찰한다."]]],[3,1,"생물의 한살이","배추흰나비 애벌레를 관찰해 볼까요",[["갓 나온 애벌레","알에서 나온 작은 애벌레를 관찰했다.","애벌레가 잎에서 움직이기 시작했다.","알에서 부화하면 애벌레 단계가 된다.","애벌레가 먹은 잎의 정확한 질량","같은 개체를 며칠 동안 추적 관찰한다."],["잎을 먹는 애벌레","배추 잎 위 애벌레가 잎을 갉아 먹었다.","잎 가장자리에 먹은 자국이 생겼다.","애벌레는 먹이를 먹으며 자란다.","애벌레의 하루 총 섭취량","먹은 잎 넓이를 일정 간격으로 비교한다."],["몸의 길이 변화","같은 애벌레의 몸길이를 며칠 간격으로 살폈다.","처음보다 길이가 늘었다.","애벌레 시기에 성장하면서 크기가 변한다.","늘어난 정확한 몸무게","눈금 도구로 몸길이를 같은 방법으로 기록한다."],["허물 벗기","애벌레 근처에 얇은 허물 같은 것이 남아 있었다.","몸이 자라며 낡은 겉껍질을 벗어 놓았다.","곤충 애벌레는 성장 중 허물을 벗을 수 있다.","허물의 정확한 화학 조성","허물 벗기 전후 모습을 안전하게 비교한다."],["몸의 마디","확대 자료에서 애벌레의 몸을 관찰했다.","몸이 여러 마디로 구분되어 보였다.","곤충 애벌레의 몸에는 구분된 마디가 있다.","몸속 기관의 정확한 길이","몸의 여러 부분을 그림으로 기록한다."]]],[3,1,"생물의 한살이","배추흰나비 번데기와 어른벌레를 관찰해 볼까요",[["움직임 적은 번데기","애벌레가 자란 뒤 번데기가 된 모습을 관찰했다.","번데기는 애벌레보다 움직임이 적었다.","번데기는 어른벌레로 변하는 발달 단계다.","변태가 끝나는 정확한 시각","번데기 겉모습을 매일 기록한다."],["번데기의 색","번데기를 며칠 동안 관찰했다.","시간이 지나면서 색과 모습이 조금 변했다.","번데기 안에서 발달이 진행될 수 있다.","안에서 일어나는 모든 기관 변화","색 변화와 우화 시기를 비교한다."],["나온 어른벌레","번데기에서 어른벌레가 나왔다.","접혀 있던 날개가 펴지는 모습이 보였다.","곤충의 어른벌레 단계에는 날개가 발달한다.","처음 날 수 있기까지 정확한 시간","날개가 펴지는 과정을 방해하지 않고 살핀다."],["꽃에 앉는 나비","꽃밭에서 어른 배추흰나비를 관찰했다.","나비가 꽃에 앉아 긴 입 부분을 이용했다.","어른벌레는 애벌레와 몸모양과 먹이 활동이 다르다.","나비의 하루 꽃 방문 수","애벌레와 어른벌레의 먹이 활동을 비교한다."],["알 낳는 어른벌레","어른 배추흰나비가 배추 잎에 알을 낳았다.","어른벌레가 다음 세대의 알을 남겼다.","어른벌레는 성장한 뒤 번식을 할 수 있다.","한 마리가 평생 낳는 알의 정확한 수","잎 위치별 알의 분포를 조사한다."]]],[3,1,"생물의 한살이","배추흰나비의 한살이를 알아볼까요",[["알부터 애벌레","배추흰나비의 알과 애벌레 사진을 날짜순으로 정리했다.","알 이후 애벌레가 나왔다.","배추흰나비는 알에서 애벌레로 성장한다.","각 단계의 정확한 지속 일수","같은 개체를 순서대로 날짜를 붙여 기록한다."],["애벌레 다음","먹이를 먹고 자란 애벌레의 변화를 관찰했다.","애벌레가 번데기가 됐다.","배추흰나비는 번데기 단계를 거친다.","번데기 내부 온도의 변화량","애벌레와 번데기의 움직임을 비교한다."],["번데기의 우화","번데기에서 어른벌레가 나왔다.","날개가 있는 나비 모습이 보였다.","배추흰나비는 완전 변태를 한다.","우화 때 소비한 에너지","변화 순서를 알·애벌레·번데기·어른벌레로 정리한다."],["성충의 번식","어른벌레가 다른 배추 잎에 알을 낳았다.","새로운 알이 생겨 한살이가 이어졌다.","생물은 성장하고 번식하며 다음 세대로 이어진다.","알마다 부화할 확률","알 낳는 장소를 방해하지 않고 관찰한다."],["성장 단계 비교","알·애벌레·번데기·어른벌레 모습을 비교했다.","몸의 모양과 움직임이 단계마다 달랐다.","배추흰나비는 성장하며 모습이 크게 달라진다.","각 단계의 정확한 체중","단계별 몸의 특징을 비교표로 정리한다."]]],[3,1,"생물의 한살이","씨가 싹 트는 데 필요한 조건은 무엇일까요",[["물 준 씨앗","같은 온도에서 씨앗 두 무리 중 한쪽에만 물을 주었다.","물을 준 쪽에서 싹이 텄다.","대부분 씨앗의 발아에는 물이 필요하다.","각 씨앗이 흡수한 정확한 물의 양","물의 유무만 달리해 여러 번 반복한다."],["차가운 곳 씨앗","같은 양의 물을 준 씨앗을 차가운 곳과 따뜻한 곳에 두었다.","너무 차가운 곳에서는 싹이 늦게 텄다.","씨가 싹 트는 데 알맞은 온도 조건이 중요하다.","씨앗 내부 효소 활성도","온도만 바꿔 싹튼 날짜를 비교한다."],["밀폐된 병","물은 충분하지만 공기가 통하지 않는 조건에 씨앗을 두었다.","공기가 통하는 조건보다 싹이 잘 트지 않았다.","씨앗의 발아에는 호흡에 필요한 산소가 중요하다.","씨앗마다 사용한 산소량","공기 공급 여부를 달리해 비교한다."],["빛 없는 상자","강낭콩 씨앗에 물과 공기를 공급하고 어두운 곳에 두었다.","빛이 없어도 싹이 트는 모습을 볼 수 있었다.","강낭콩 발아에는 빛 자체가 필수 조건은 아니다.","싹튼 뒤 잎의 엽록소량","빛 유무에 따라 발아 시기를 비교한다."],["종류 다른 씨앗","같은 물과 온도 조건에 강낭콩과 옥수수 씨앗을 두었다.","씨앗마다 싹트는 시기가 달랐다.","씨앗 종류도 발아 특징에 영향을 줄 수 있다.","모든 씨앗 종의 평균 발아 시간","종류별 싹튼 씨앗 수를 기록한다."]]],[3,1,"생물의 한살이","식물이 자라는 데 필요한 조건은 무엇일까요",[["빛 부족한 화분","같은 종류의 어린 식물 두 개를 한쪽은 밝게, 다른 쪽은 어둡게 두었다.","오래 어두운 곳에 둔 식물의 잎이 창백해졌다.","식물이 정상적으로 자라는 데 빛이 중요하다.","잎이 만든 정확한 양분량","빛만 바꾸어 줄기와 잎 색을 기록한다."],["물 부족","같은 화분 두 개 중 한쪽에 물을 오래 주지 않았다.","물을 주지 않은 식물이 시들었다.","식물의 생장에는 적절한 물 공급이 필요하다.","시든 잎의 실제 수분 함량","물의 양을 달리해 생장 상태를 관찰한다."],["영양분 부족한 흙","같은 식물을 서로 다른 양분 조건의 흙에 심었다.","양분이 부족한 화분에서 자람이 더뎠다.","생장에는 여러 무기 양분도 필요하다.","뿌리가 흡수한 특정 이온량","흙의 양분 조건만 바꿔 성장량을 잰다."],["환기 조건","식물을 빛과 물이 있는 장소에 두고 공기 순환 상태를 살폈다.","공기 순환 조건에 따라 화분 주변 환경이 달랐다.","식물은 공기 속 이산화탄소 등을 이용한다.","실제 흡수된 이산화탄소량","환기 조건과 생장 변화를 따로 비교한다."],["온도 비교","같은 종류 어린 식물을 지나치게 추운 곳과 알맞게 따뜻한 곳에 두었다.","너무 추운 곳에서 성장이 느렸다.","식물 생장에는 알맞은 온도 범위가 있다.","식물 세포의 실제 분열 횟수","온도만 바꿔 일주일 키 변화를 측정한다."]]],[3,1,"생물의 한살이","여러 가지 생물의 한살이를 알아볼까요",[["개구리의 변화","개구리 알과 올챙이, 다 자란 개구리 그림을 시간순으로 비교했다.","올챙이에는 꼬리가 있지만 어른 개구리에는 다리가 발달했다.","개구리는 한살이 동안 몸모양이 변한다.","올챙이의 정확한 생존율","성장 단계별 생활환경도 함께 비교한다."],["잠자리의 한살이","물속 유충과 날개 달린 어른 잠자리를 자료로 비교했다.","어린 시절에는 물속에서 살고 어른이 되어 날았다.","잠자리는 번데기 없이 성장하는 불완전 변태를 한다.","물속 유충의 정확한 수명","유충과 성충의 이동 모습을 비교한다."],["콩의 한살이","강낭콩 씨앗과 싹, 꽃, 열매 단계를 살폈다.","열매 속에 다음 세대의 씨가 생겼다.","식물은 씨에서 자라 꽃과 열매를 맺는다.","하나의 씨가 만든 총 양분량","씨·싹·꽃·열매 순서를 날짜별로 기록한다."],["나비와 잠자리","배추흰나비와 잠자리의 한살이 단계를 나란히 놓았다.","나비는 번데기를 거치지만 잠자리는 거치지 않았다.","동물마다 발달 단계의 구성이 다르다.","두 종의 전체 평균 수명","변태 단계와 어린 개체 모습의 차이를 비교한다."],["닭의 한살이","닭의 알에서 병아리가 나온 뒤 자라는 모습을 사진으로 살폈다.","병아리가 점차 자라 어른 닭이 됐다.","닭은 알에서 나오지만 곤충처럼 번데기를 거치지 않는다.","개체별 정확한 체온","병아리와 어른 닭의 깃털·몸크기를 비교한다."]]],[4,1,"자석의 이용","자석과 여러 가지 물체를 가까이 하면 어떻게 될까요",[["철못과 자석","막대자석을 철못 가까이 가져갔다.","철못이 자석에 끌려왔다.","자석은 철로 된 물체를 끌어당길 수 있다.","당기는 힘의 정확한 크기","자석과 철못 사이 거리를 바꾸어 비교한다."],["나무 젓가락","자석을 나무 젓가락에 가까이 했다.","젓가락이 자석 쪽으로 움직이지 않았다.","대부분의 나무는 자석에 끌리지 않는다.","나무의 정확한 밀도","철젓가락과 나무젓가락을 비교한다."],["알루미늄 포일","일반 막대자석을 얇은 알루미늄 포일 가까이 댔다.","포일이 철못처럼 끌려오지 않았다.","흔한 자석에 끌리는 성질은 물질마다 다르다.","포일의 전체 질량","철·알루미늄·구리 조각을 같은 자석으로 비교한다."],["동전 종류","다른 종류 동전을 자석 가까이 대 보았다.","어떤 동전은 끌렸고 어떤 동전은 잘 끌리지 않았다.","금속이라고 모두 같은 자기적 성질을 갖는 것은 아니다.","동전별 자세한 합금 비율","동전 재료에 따른 반응을 표로 기록한다."],["종이 너머 클립","종이 한 장 위에 클립을 놓고 종이 아래 자석을 움직였다.","클립이 종이를 사이에 두고 자석을 따라 움직였다.","자기력은 직접 접촉하지 않아도 작용할 수 있다.","종이를 통과한 자기장의 수치","종이 두께를 바꿔 클립 이동을 비교한다."]]],[4,1,"자석의 이용","자석과 철로 된 물체 사이에 작용하는 힘은 어떤 특징이 있을까요",[["가까운 철구슬","철구슬을 자석 바로 가까이 놓았다.","자석에 닿기 전부터 철구슬이 움직였다.","자기력은 닿지 않은 곳에도 작용할 수 있다.","자기력의 정확한 뉴턴 값","자석과 철구슬 사이 거리를 측정한다."],["멀리 놓은 클립","클립을 막대자석에서 멀리 놓고 천천히 접근시켰다.","일정 거리 가까이에서 클립이 끌려왔다.","자석과의 거리는 자기력의 영향을 받는다.","움직임이 시작되는 정확한 거리","위치를 바꿔 움직이기 시작한 거리를 잰다."],["철가루 모형","자석 가까이에 놓인 철가루를 얇은 종이 위에서 관찰했다.","철가루가 자석 주변의 무늬를 이루었다.","자석 주위에는 철가루에 힘이 작용하는 영역이 있다.","각 철가루의 정확한 질량","자석 방향을 바꿔 철가루 배열을 비교한다."],["막대자석 두 종류","크기가 다른 막대자석과 같은 클립을 사용했다.","클립이 움직이는 거리와 모습이 달랐다.","자석의 힘은 크기뿐 아니라 자석 자체의 세기에 따라 다르다.","두 자석의 실제 자기장 세기","같은 클립·거리 조건으로 여러 번 비교한다."],["철못이 붙은 자석","자석에 철못 여러 개를 차례로 붙였다.","붙은 못을 통해 아래쪽 못도 매달렸다.","철은 자석 가까이에서 자화될 수 있다.","철못마다 생긴 자기의 정확한 세기","자석을 멀리한 뒤 못이 남아 붙는지 확인한다."]]],[4,1,"자석의 이용","자석에서 철로 된 물체를 당기는 힘이 가장 큰 부분은 어디일까요",[["막대자석 끝","막대자석의 끝과 가운데에 각각 클립을 가까이 댔다.","끝부분에 클립이 더 잘 붙었다.","막대자석 양 끝인 극에서 자석의 힘이 비교적 강하다.","끝부분의 자기력 수치","각 위치에 붙는 클립 수를 같은 조건에서 비교한다."],["자석 위 철가루","종이 아래 막대자석을 두고 위에 철가루를 뿌렸다.","철가루가 막대자석 양 끝에 더 많이 모였다.","자석 양 끝 극 부근에서 자기력이 강하게 나타난다.","철가루 하나의 정확한 자기 모멘트","종이를 바꾸지 않고 자석 위치를 이동해 본다."],["중앙에 클립","막대자석 가운데에 클립을 붙여 보았다.","양 끝보다 잘 붙지 않았다.","막대자석의 가운데와 양 끝은 힘의 크기가 다르다.","자석 내부 자성체의 미세 구조","막대자석을 길이 방향으로 여러 구간 나눠 비교한다."],["끝부분 양쪽","막대자석의 왼쪽 끝과 오른쪽 끝에 같은 클립을 놓았다.","양쪽 끝에서 클립이 끌렸다.","막대자석에는 일반적으로 두 개의 극이 있다.","두 극이 당기는 힘의 정확한 차이","같은 거리의 철못을 양끝에 대어 비교한다."],["말굽자석의 극","U자 모양 말굽자석 두 끝에 철못을 가까이 했다.","U자 자석의 두 끝에서 철못이 끌렸다.","자석의 극은 형태가 달라도 특정 끝부분에 나타날 수 있다.","두 끝 사이 자기장 세기","막대자석과 말굽자석의 극 위치를 비교한다."]]],[4,1,"자석의 이용","자석과 자석을 가까이 하면 어떻게 될까요",[["N극과 S극","한 자석 N극을 다른 자석 S극 가까이 했다.","두 자석이 서로 끌어당겼다.","다른 극끼리는 서로 끌어당긴다.","실제 당기는 힘 크기","극 표시를 바꿔 같은 거리에서 비교한다."],["N극과 N극","두 막대자석 N극끼리 가까이 했다.","서로 밀어내며 멀어졌다.","같은 극끼리는 밀어내는 힘을 낸다.","밀려난 정확한 거리","S극끼리도 가까이 해 본다."],["S극과 S극","두 자석 S극을 같은 거리로 가까이 했다.","두 자석이 서로 밀어냈다.","같은 이름의 자석 극은 서로 밀어낸다.","두 자석의 실제 질량","N극끼리일 때와 움직임을 비교한다."],["회전 가능한 자석","실로 매단 자석 가까이에 다른 자석을 가져갔다.","매달린 자석이 돌아가 방향을 바꾸었다.","자석끼리 작용하는 힘은 회전도 일으킬 수 있다.","자석이 회전한 정확한 각도","가져가는 극을 바꿔 회전 방향을 비교한다."],["극 이름 숨기기","극 표시를 가린 두 자석 끝을 가까이 대었다.","서로 밀어내는 반응이 나타났다.","밀어내면 서로 같은 극이라는 단서를 얻는다.","두 극이 각각 N인지 S인지","표시가 있는 자석으로 극의 이름을 확인한다."]]],[4,1,"자석의 이용","나침반과 자석을 가까이 하면 어떻게 될까요",[["기본 나침반","자석을 멀리한 나침반을 평평한 책상에 두었다.","나침반 바늘이 일정한 방향으로 정렬됐다.","나침반은 지구 자기장의 영향을 받아 방향을 알려준다.","지역의 정확한 편각 수치","나침반을 다른 위치로 옮겨 방향을 확인한다."],["자석 가까이","나침반 옆에 막대자석을 가까이 했다.","바늘이 처음 방향에서 돌아갔다.","주변 자석의 자기장이 나침반 바늘에 영향을 준다.","바늘이 받은 정확한 토크","자석까지 거리를 바꿔 바늘 각도를 기록한다."],["N극 접근","나침반의 북쪽을 가리키는 바늘 끝 가까이 자석 N극을 가져갔다.","바늘이 가까운 N극에서 멀어지려는 방향으로 움직였다.","같은 극은 서로 밀어내는 경향이 있다.","실제로 움직인 각도의 정확한 값","S극으로 바꿔 바늘 움직임을 비교한다."],["자석 멀리하기","나침반에서 가까이 있던 자석을 다시 치웠다.","바늘이 처음의 일정한 방향으로 돌아왔다.","외부 자석의 영향이 줄면 지구 자기장 방향을 따른다.","바늘이 돌아오는 데 걸린 시간","자석 거리별로 바늘 방향을 확인한다."],["금속 책상","철제 책상 위의 나침반을 사용했다.","나침반 바늘이 다른 장소와 다른 방향을 가리킬 수 있었다.","가까운 금속과 자석은 나침반 관찰에 영향을 줄 수 있다.","철제 책상의 실제 자화 정도","철제 책상과 나무 책상에서 관찰을 비교한다."]]],[4,1,"자석의 이용","우리 생활에서 자석을 어떻게 이용할까요",[["냉장고 문","냉장고 문 안쪽에 자석이 있는 부분을 살폈다.","문이 닫힐 때 자석의 끌어당김이 작용했다.","자석은 문이 잘 닫혀 있도록 하는 데 활용된다.","문을 떼는 데 필요한 정확한 힘","자석 유무에 따른 닫힘 상태를 비교한다."],["자석식 수납함","철제 칠판에 자석이 달린 수납함을 붙였다.","수납함이 칠판 표면에 붙어 있었다.","자기력은 물체를 고정하는 데 쓰인다.","수납함의 최대 적재 무게","안전하게 무게를 조금씩 늘려 붙는 정도를 살핀다."],["재활용 시설","분류대에서 자석으로 철로 된 물체를 골라냈다.","철이 든 일부 물체가 자석 쪽으로 이동했다.","재활용 과정에서 자석으로 자성 재료를 분리할 수 있다.","전체 재활용율","금속 종류에 따라 자석 반응을 비교한다."],["나침반 길찾기","야외에서 나침반을 들고 방향을 확인했다.","바늘로 대략 북쪽 방향을 알아봤다.","자석 바늘은 방위를 짐작하는 데 쓰인다.","출발지에서 목적지까지의 거리","지도와 나침반 방향을 함께 확인한다."],["자석 장난감","자석이 들어 있는 블록 두 개를 붙였다.","방향에 따라 붙거나 밀어내는 움직임이 달랐다.","극 사이 힘을 이용한 놀이 도구를 만들 수 있다.","자석 블록의 실제 자기장 세기","극 방향을 바꿔 연결 방식을 비교한다."]]],[4,1,"물의 상태 변화","물의 상태 변화를 알아볼까요",[["얼음컵","얼음 조각을 따뜻한 곳에 두었다.","얼음이 녹아 액체 물이 됐다.","고체 얼음은 열을 받으면 액체로 변할 수 있다.","녹는 데 필요한 정확한 열량","시간별 얼음과 물의 양을 기록한다."],["냉동실 물","물컵을 냉동실에 오래 두었다.","액체 물이 고체 얼음으로 얼었다.","물이 열을 잃으면 어는 상태 변화가 일어난다.","정확한 냉동실 온도 변화","얼기 전후 용기 속 모습을 비교한다."],["젖은 수건","젖은 수건을 실내 빨랫줄에 널었다.","시간이 지나 수건의 물기가 줄었다.","액체 물이 공기 중 수증기가 되는 증발이 일어난다.","실제로 증발한 물의 분자 수","수건 무게를 일정 간격으로 재어 본다."],["차가운 유리","습한 날 찬 컵을 실내에 놓았다.","컵 바깥에 물방울이 맺혔다.","공기 중 수증기가 차가운 표면에 응결한다.","공기 속 수증기의 정확한 양","찬 컵과 실온 컵 표면을 비교한다."],["끓는 냄비","냄비 속 물을 충분히 가열했다.","물속에서 기포가 발생하여 위로 올라왔다.","끓음은 액체 내부에서도 기화가 일어나는 현상이다.","냄비에서 나온 수증기 전체 질량","가열 전후 물의 양을 안전하게 관찰한다."]]],[4,1,"물의 상태 변화","물의 상태 변화의 예를 찾아볼까요",[["겨울 고인 물","기온이 내려간 밤에 얕은 물웅덩이를 보았다.","액체 물의 표면이 얼음으로 바뀌었다.","어는 현상은 자연에서 볼 수 있는 상태 변화다.","얼음층의 정확한 두께","기온이 오른 뒤 얼음 변화를 관찰한다."],["봄날 눈","날이 따뜻해진 오후 잔디 위 눈을 살폈다.","쌓였던 눈이 녹아 물이 됐다.","녹음은 고체가 액체로 바뀌는 상태 변화다.","완전히 녹는 시각","그늘과 햇볕의 녹는 모습을 비교한다."],["빨래 건조","젖은 운동복을 그늘진 통풍 장소에 널었다.","시간이 지나 물기가 사라졌다.","물의 증발은 끓지 않아도 일어난다.","옷에서 증발한 정확한 물의 질량","바람 조건별 건조 시간을 비교한다."],["냉장고 물방울","냉장고에서 꺼낸 찬 병 겉에 물방울이 생겼다.","병 바깥면이 젖어 보였다.","수증기의 응결이 생활 속에서 나타난다.","병 안에 있던 물의 정확한 양","병 표면 온도에 따른 물방울을 비교한다."],["식은 밥솥 뚜껑","따뜻한 밥솥에서 나온 수증기가 비교적 찬 뚜껑에 닿았다.","뚜껑 안쪽에 물방울이 맺혔다.","기체 수증기는 식으면 액체로 변할 수 있다.","맺힌 물방울의 정확한 수","뚜껑의 온도와 물방울 양을 비교한다."]]],[4,1,"물의 상태 변화","물이 얼 때와 얼음이 녹을 때에는 어떤 변화가 있을까요",[["얼음틀","같은 양의 물을 얼음틀에 넣어 얼렸다.","얼음이 되며 부피가 늘었다.","물은 얼 때 일반적으로 부피가 커진다.","얼음의 정확한 결정 크기","눈금 용기에서 얼기 전후 부피를 비교한다."],["질량 비교","밀폐된 용기에 물을 담아 얼린 뒤 같은 저울로 재었다.","용기와 내용물의 전체 질량이 거의 같았다.","물의 상태가 바뀌어도 물질의 질량은 보존된다.","얼어 있는 물의 밀도","같은 용기에서 녹인 뒤 다시 질량을 잰다."],["녹는 얼음","실내에서 얼음을 접시 위에 놓았다.","얼음 주변에 물이 점차 생겼다.","고체 얼음이 열을 얻어 액체로 녹는다.","녹기 시작한 정확한 분자 위치","온도와 물의 양을 시간별로 기록한다."],["얼음이 떠 있는 이유","같은 컵의 물에 얼음 조각을 띄웠다.","얼음이 물 위에 떠 있었다.","얼음은 같은 물질의 액체 물보다 밀도가 작다.","얼음 조각의 정확한 부피","얼음과 같은 부피 물의 질량을 비교한다."],["녹는 중 온도","얼음이 충분히 있는 컵을 일정하게 가열하며 온도를 기록했다.","순수한 얼음이 녹는 동안 온도가 약 0°C 부근에 머물렀다.","녹는 과정의 열은 상태 변화에 사용된다.","가열기의 실제 열손실량","시간별 얼음 양과 온도를 함께 기록한다."]]],[4,1,"물의 상태 변화","물이 증발할 때와 끓을 때의 변화를 관찰해 볼까요",[["젖은 접시","넓은 접시에 소량의 물을 펴서 두었다.","끓이지 않아도 물이 점차 줄었다.","증발은 액체 표면에서 다양한 온도에 일어난다.","매초 증발한 정확한 분자 수","접시 표면 넓이를 바꿔 비교한다."],["끓는 비커","안전한 장치에서 물을 충분히 가열했다.","물속 곳곳에서 기포가 생겨 올라왔다.","끓음은 액체 내부에서도 기화가 일어나는 현상이다.","기포마다 들어 있는 기체의 정확한 양","가열하는 동안 기포와 수온을 관찰한다."],["넓은 컵과 좁은 컵","같은 양의 물을 표면적이 다른 두 용기에 넣었다.","넓은 용기에서 물이 더 빨리 줄어드는 경향을 보였다.","노출된 물 표면 넓이는 증발 속도에 영향을 줄 수 있다.","실내 습도의 정확한 값","온도와 바람을 맞추고 용기 넓이만 바꾼다."],["바람 부는 곳","같은 젖은 천을 바람이 있는 곳과 거의 없는 곳에 두었다.","바람이 있는 쪽에서 물기가 빨리 줄었다.","공기 이동은 증발에 영향을 준다.","천 속 물의 분자 수","천 재질과 물의 양을 맞춰 반복한다."],["온도 차 비교","따뜻한 장소와 서늘한 장소에 같은 물컵을 놓았다.","따뜻한 장소에서 물이 더 빨리 줄었다.","온도는 일반적으로 물의 증발 속도에 영향을 준다.","각 장소의 정확한 수증기압","같은 시간에 남은 물의 질량을 비교한다."]]],[4,1,"물의 상태 변화","수증기가 응결할 때의 변화를 관찰해 볼까요",[["찬 병의 표면","냉장고에서 꺼낸 차가운 병을 실내에 두었다.","병 겉에 작은 물방울이 생겼다.","실내 공기 중 수증기가 차가운 표면에서 응결했다.","공기 중 전체 수증기 질량","실온 병과 차가운 병의 표면을 비교한다."],["냄비 뚜껑","수증기가 올라오는 냄비 위에 상대적으로 찬 뚜껑을 두었다.","뚜껑 아래에 물방울이 모였다.","따뜻한 수증기가 식으면 액체로 응결한다.","뚜껑의 정확한 온도","뚜껑을 충분히 식히거나 데운 조건을 비교한다."],["욕실 거울","따뜻한 물로 샤워한 뒤 차가운 거울을 관찰했다.","거울이 흐려지고 작은 물방울이 맺혔다.","습한 공기 속 수증기가 비교적 찬 거울에 응결했다.","욕실 공기의 정확한 수증기량","환기 전후 거울의 변화를 비교한다."],["풀잎의 이슬","맑은 날 새벽 풀잎을 관찰했다.","잎 표면에 이슬방울이 맺혀 있었다.","차가운 표면에서 수증기가 물방울로 변할 수 있다.","이슬방울 전체의 실제 질량","새벽과 낮의 잎 온도를 비교한다."],["수증기와 김","끓는 물 위의 보이지 않는 수증기가 찬 공기에서 식었다.","공기 중에 작은 물방울인 흰 김이 나타났다.","보이는 흰 김은 주로 응결된 미세한 물방울이다.","김 속 물방울의 평균 크기","물에서 거리를 바꿔 김의 모습을 관찰한다."]]],[4,1,"물의 상태 변화","물의 중요성을 알아볼까요",[["물 마시기","운동 뒤 학생들이 안전한 식수를 마셨다.","물을 마셔 몸속 수분을 보충했다.","물은 생물이 살아가는 데 꼭 필요한 자원이다.","학생마다 하루 필요한 정확한 물의 양","활동에 따라 마시는 물의 양을 기록한다."],["화분에 물주기","시든 화분에 알맞게 물을 주었다.","시간이 지나 잎의 상태가 나아졌다.","식물의 생장과 물질 이동에도 물이 필요하다.","잎이 실제로 흡수한 물의 양","물을 준 날과 주지 않은 날을 비교한다."],["깨끗한 생활","손을 씻을 때 흐르는 물을 사용했다.","손에 묻은 일부 오염 물질이 씻겨 나갔다.","물은 위생을 유지하는 데 쓰인다.","제거된 미생물의 정확한 수","손 씻는 시간과 방법을 비교한다."],["농업용수","농부가 논에 물길을 내어 물을 공급했다.","논의 흙이 물을 머금었다.","농사는 작물이 자라는 데 필요한 물을 이용한다.","수확량의 정확한 변화","물 공급량과 흙의 습도를 관찰한다."],["하천의 생물","강물 속 물고기와 수초를 관찰했다.","여러 생물이 물에서 살아가고 있었다.","물은 많은 생물의 서식 공간이기도 하다.","강 전체의 생물 개체 수","계절별 물속 생물의 종류를 기록한다."]]],[4,1,"물의 상태 변화","물 부족 현상과 물을 얻는 장치를 알아볼까요",[["가뭄 지역","비가 적게 온 마을의 저수지 수위를 기록했다.","저수지 물이 이전보다 줄었다.","강수량 감소와 사용량은 물 부족에 영향을 줄 수 있다.","가뭄이 끝나는 정확한 시각","강수량과 물 사용량을 함께 조사한다."],["빗물 저장통","지붕에서 흘러내린 빗물을 저장통에 모았다.","비가 온 뒤 통에 물이 모였다.","빗물 모으기는 물을 확보하는 한 방법이다.","저장된 물이 마실 수 있을 만큼 안전한지","빗물 사용 목적에 맞는 정화 절차를 살핀다."],["염수의 증발","소금이 녹은 물을 간단한 증류 모형에서 안전하게 가열하고 응결시켰다.","증발한 수증기에서 다시 액체 물을 모았다.","증류는 녹아 있던 물질과 물을 나누는 데 쓸 수 있다.","모아진 물의 실제 염분 농도","모은 물의 성질을 검사한다."],["햇빛 증류 장치","투명 덮개 아래 바닷물 모형을 두고 햇빛을 받게 했다.","덮개 안쪽에서 생긴 물방울을 한쪽에 모았다.","증발과 응결을 이용하면 물을 분리할 수 있다.","하루 동안 모을 수 있는 실제 물의 양","날씨에 따라 수집량을 기록한다."],["누수 줄이기","물탱크 아래 새는 수도관을 수리했다.","수리 뒤 같은 시간 동안 새는 물이 줄었다.","물을 새지 않게 관리하는 것도 물 부족을 줄이는 데 도움 된다.","한 달간 절약한 정확한 물의 양","수리 전후 물 계량기 기록을 비교한다."]]],[4,1,"땅의 변화","흐르는 물은 땅의 모습을 어떻게 변화시킬까요",[["모래 경사면","모래가 쌓인 경사면에 물을 흘려보냈다.","흐르는 물이 모래를 깎고 아래로 운반했다.","흐르는 물은 땅을 깎는 침식을 일으킨다.","이동한 모래의 정확한 질량","물 흐름을 바꿔 침식된 양을 비교한다."],["경사 큰 흙길","기울기가 다른 두 흙길 모형에 같은 물을 부었다.","가파른 쪽에서 흙이 더 많이 쓸려갔다.","흐름의 빠르기는 침식에 영향을 줄 수 있다.","물의 실제 유속 수치","경사만 바꿔 흙 이동량을 비교한다."],["느린 하천","흐름이 느려진 작은 물길 끝을 관찰했다.","운반되던 모래가 바닥에 쌓였다.","물이 느려지면 퇴적이 일어나기 쉽다.","퇴적물의 정확한 입자 수","물 흐름을 줄이고 퇴적된 두께를 잰다."],["비 뒤의 골짜기","강한 비가 지난 뒤 언덕 흙길을 관찰했다.","작은 홈이 깊어져 물길이 생겼다.","빗물이 흐르며 땅의 표면을 바꿀 수 있다.","그 사이 내린 비의 정확한 양","비 오기 전후 같은 위치를 비교한다."],["돌의 이동","하천에서 모래와 작은 자갈의 이동 모습을 살폈다.","작은 알갱이가 물과 함께 아래쪽으로 이동했다.","흐르는 물은 퇴적물을 운반한다.","자갈 하나의 실제 속력","알갱이 크기별 이동 거리를 비교한다."]]],[4,1,"땅의 변화","강 주변 지형은 어떤 특징이 있을까요",[["굽은 강","지도에서 크게 굽은 하천 구간을 살폈다.","강이 구불구불 돌아 흐르고 있었다.","하천 흐름은 굽은 지형을 만들 수 있다.","강이 굽기 시작한 연도","굽은 안쪽과 바깥쪽의 모래 상태를 비교한다."],["강 안쪽 모래","굽은 강의 안쪽 모래톱을 관찰했다.","물이 느려지는 쪽에 모래가 쌓였다.","굽은 강의 안쪽에는 퇴적이 잘 일어날 수 있다.","퇴적된 모래의 전체 질량","물 흐름과 모래톱 위치를 함께 기록한다."],["강 바깥쪽 침식","굽은 강의 바깥쪽 강둑을 관찰했다.","일부 둑이 물에 깎인 모습이었다.","굽은 구간 바깥쪽에는 침식이 일어나기 쉽다.","깎여 나간 땅의 정확한 부피","두 강둑의 변화량을 시간에 따라 비교한다."],["평야를 지나는 강","넓고 평탄한 지역을 흐르는 강을 보았다.","강 옆에 모래와 진흙이 쌓인 땅이 있었다.","강은 퇴적물을 옮기며 주변 평야 형성에 영향을 준다.","평야가 생긴 정확한 시기","강 주변 흙과 먼 곳의 흙을 비교한다."],["강 하구의 모습","강이 바다와 만나는 곳의 지도를 살폈다.","강이 운반한 퇴적물이 하구에 모여 있었다.","강 하구에서 퇴적 지형이 만들어질 수 있다.","퇴적물이 쌓이는 연간 속도","하구 지도를 시기별로 비교한다."]]],[4,1,"땅의 변화","화산이란 무엇일까요",[["산꼭대기 분화구","화산 모형에서 꼭대기의 움푹한 부분을 관찰했다.","분화구처럼 보이는 입구가 있었다.","화산은 땅속 마그마가 지표로 나오는 활동과 관련된다.","분화구의 정확한 깊이","화산의 여러 모양을 비교한다."],["용암의 이동","화산 분출 모형에서 붉은 물질이 아래로 흐르는 모습을 보았다.","지표로 나온 물질이 사면 아래로 이동했다.","지표로 나온 마그마를 용암이라고 한다.","실제 용암의 온도","경사에 따라 흐르는 방향을 관찰한다."],["화산체의 모습","화산 사진의 산비탈과 꼭대기를 비교했다.","분출물이 쌓여 산 모양 지형이 나타났다.","화산 분출물은 쌓여 지형을 만들 수 있다.","산이 형성된 정확한 연대","다른 화산의 높이와 경사를 비교한다."],["분출 전후","화산이 활동하기 전과 후의 지형 자료를 비교했다.","분출 뒤 주변 지형 일부가 달라졌다.","화산 활동은 지표의 모습을 바꿀 수 있다.","활동 당시의 정확한 분출량","같은 지역의 시기별 지도를 비교한다."],["휴식하는 화산","현재 분출 중이지 않은 화산을 살펴봤다.","산에서 용암이 나오지 않고 있었다.","화산은 항상 분출하는 것이 아니다.","앞으로 분출할 정확한 시각","화산의 지진·가스 관측 기록을 살펴본다."]]],[4,1,"땅의 변화","화산 활동으로 어떤 물질이 나올까요",[["용암","화산에서 붉게 빛나는 액체 물질이 흘러내렸다.","지표로 나온 용암이 비탈을 따라 흘렀다.","용암은 분출한 마그마가 지표에 나온 것이다.","용암의 정확한 화학 조성","식은 뒤 생긴 암석 종류를 살핀다."],["화산재","화산 분출 뒤 주변에 아주 고운 가루가 쌓였다.","작은 입자의 화산재가 땅과 건물에 내려앉았다.","화산 분출로 고체 미세 입자가 나올 수 있다.","화산재 입자 전체의 정확한 개수","안전한 자료로 화산재의 알갱이 크기를 살핀다."],["화산가스","화산 분출 자료에서 수증기와 여러 기체가 나왔다.","분출구 주변에 기체가 퍼졌다.","화산 활동은 가스도 방출할 수 있다.","분출한 가스의 정확한 비율","화산 관측소의 가스 종류 자료를 조사한다."],["화산탄","화산 가까운 곳에서 커다란 분출물 조각이 발견됐다.","굳은 조각들이 주변에 떨어져 있었다.","큰 고체 분출물도 화산 활동에서 나올 수 있다.","조각 하나의 실제 운동에너지","분출물의 크기와 쌓인 위치를 비교한다."],["식은 용암","분출이 끝난 지역에서 어두운 암석을 관찰했다.","용암이 식어 굳은 바위가 있었다.","마그마가 지표에서 식으면 화산암이 된다.","그 용암이 식은 정확한 시간","암석의 구멍과 색을 관찰한다."]]],[4,1,"땅의 변화","화성암을 분류해 볼까요",[["현무암의 구멍","검고 구멍이 보이는 암석 표본을 살폈다.","표면에 작은 구멍들이 많이 있었다.","일부 현무암에는 기체 흔적으로 구멍이 있다.","표본이 생성된 정확한 연대","다른 현무암 표본의 구멍 유무도 비교한다."],["화강암의 알갱이","밝은 색과 비교적 큰 광물 알갱이가 보이는 표본을 살폈다.","서로 다른 색의 광물 결정이 구별됐다.","화강암은 땅속에서 천천히 식어 큰 결정을 만들 수 있다.","광물별 정확한 질량 비율","확대경으로 결정의 크기를 비교한다."],["현무암과 화강암","현무암과 화강암의 겉모습을 비교했다.","현무암은 고운 입자가 많고 화강암은 비교적 굵은 결정을 보였다.","마그마가 식는 조건은 결정 크기에 영향을 준다.","두 표본의 생성 장소","표본별 광물 결정 크기를 측정한다."],["모형 냉각 속도","빠르게 식힌 결정 모형과 천천히 식힌 모형을 비교했다.","빨리 식힌 모형에 작은 결정이 나타났다.","냉각 속도 차이가 결정 크기에 영향을 줄 수 있다.","실제 암석의 냉각 온도 변화","냉각 시간과 결정 크기를 표로 정리한다."],["암석의 색","어두운 표본과 밝은 표본을 나란히 놓았다.","두 암석의 색과 알갱이 모양이 달랐다.","화성암은 광물 조성과 생성 조건에 따라 특징이 다르다.","암석이 포함한 광물의 정밀 비율","색뿐 아니라 결정 크기와 광물도 비교한다."]]],[4,1,"땅의 변화","화산 활동은 우리 생활에 어떤 영향을 줄까요",[["화산재와 항공","화산 분출로 높은 하늘에 화산재가 퍼졌다.","항공편이 안전을 위해 운항을 멈췄다.","화산재는 항공기 운항에 위험을 줄 수 있다.","화산재의 정확한 높이","분출 정보를 확인해 항공 안전 대책을 조사한다."],["화산 주변의 토양","오래전 화산 물질이 풍화된 지역에서 농사를 지었다.","일부 땅에서 작물이 자랐다.","화산 물질로 만들어진 토양은 농업에 이용되기도 한다.","이 밭의 실제 수확량","화산 토양과 다른 토양의 성질을 비교한다."],["뜨거운 온천","화산 활동의 영향이 있는 지역에서 따뜻한 지하수가 나왔다.","지표로 따뜻한 물이 솟았다.","지열은 온천이나 에너지 자원으로 이용될 수 있다.","지하수의 정확한 온도","온천과 주변 지하수 온도를 비교한다."],["용암 피해","화산 가까운 마을에 용암이 흘러갈 위험이 있었다.","위험 구역의 주민에게 대피를 안내했다.","화산 분출은 주거지와 시설에 피해를 줄 수 있다.","용암의 정확한 이동 속력","위험 지도와 대피 경로를 살펴본다."],["화산 관측","화산 관측소에서 주변 지진과 가스 변화를 살폈다.","활동 변화를 기록하고 위험 정보를 알렸다.","관측은 화산 재해 대비에 도움이 된다.","다음 분출의 정확한 날짜","여러 관측 자료를 함께 비교한다."]]],[4,1,"땅의 변화","지진은 우리 생활에 어떤 영향을 줄까요",[["흔들린 책장","지진 때 책장이 흔들리고 물건이 떨어졌다.","가구 위 물체가 아래로 떨어졌다.","땅의 흔들림은 실내 물건의 안전에 영향을 준다.","지진의 정확한 진원 깊이","가구를 고정하는 방법을 조사한다."],["건물 밖 대피","지진이 멈춘 뒤 안전한 이동로를 확인했다.","사람들이 안내에 따라 넓은 장소로 이동했다.","지진 뒤에는 낙하물과 시설 손상에 주의해야 한다.","현장의 정확한 피해 금액","학교 대피로를 미리 점검한다."],["비상 가방","지진을 대비해 생수와 손전등을 가방에 준비했다.","정전 등 비상 상황에 쓸 물건이 모였다.","재난 준비는 지진 이후 생활 불편을 줄인다.","실제 정전 지속 시간","가정별 비상 물품을 점검한다."],["교량의 흔들림","지진으로 다리 일부에 균열이 생긴 자료를 보았다.","사람들의 통행이 임시로 제한됐다.","지진은 도로와 다리 같은 시설을 손상시킬 수 있다.","다리의 정확한 붕괴 확률","구조물 점검과 통행 관리 방법을 조사한다."],["지진 관측","지진계가 땅의 흔들림을 기록했다.","흔들림의 시간에 따른 기록이 남았다.","지진계로 지진파를 관측할 수 있다.","다음 지진 발생 시각","기록을 비교해 흔들림 차이를 살펴본다."]]],[4,1,"다양한 생물과 우리 생활","버섯과 곰팡이의 특징은 무엇일까요",[["나무 아래 버섯","비가 온 뒤 나무 아래에서 버섯을 관찰했다.","버섯의 갓과 자루 같은 모양이 보였다.","버섯은 식물과 다른 균류에 속한다.","이 버섯의 정확한 종 이름","안전하게 그림과 사진으로 균류의 모양을 비교한다."],["빵에 생긴 곰팡이","오래 둔 빵에서 곰팡이가 핀 사진을 살펴봤다.","빵 표면에 솜털처럼 퍼진 부분이 보였다.","곰팡이도 균류이며 영양분을 얻어 자란다.","곰팡이의 실제 포자 수","곰팡이 표본은 직접 만지지 않고 사진으로 관찰한다."],["버섯과 잎","버섯과 초록 식물의 겉모습을 비교했다.","버섯에는 초록 잎이 없었다.","버섯은 광합성으로 양분을 만드는 녹색 식물과 다르다.","버섯 조직의 정확한 당 함량","균류와 식물의 영양 방식 자료를 비교한다."],["습한 장소의 곰팡이","습한 욕실 모서리에 곰팡이가 생긴 사진 자료를 살폈다.","축축한 표면에 어두운 점들이 퍼졌다.","많은 곰팡이는 습한 조건에서 잘 자란다.","이 곰팡이의 정확한 학명","습도와 곰팡이 생장 자료를 비교한다."],["균류의 역할","숲의 낙엽이 썩는 자리에 균류가 나타났다.","낙엽이 분해되어 모양이 달라졌다.","균류 가운데는 죽은 생물의 물질을 분해하는 종류가 있다.","낙엽 한 장이 완전히 분해되는 시각","낙엽 분해 전후 모습을 오래 관찰한다."]]],[4,1,"다양한 생물과 우리 생활","해캄과 짚신벌레의 특징은 무엇일까요",[["해캄의 초록 실","연못에서 채집한 해캄의 현미경 사진을 보았다.","길고 실 같은 초록색 몸 구조가 이어졌다.","해캄은 물에서 광합성을 하는 조류이다.","해캄의 정확한 전체 세포 수","해캄을 구성한 세포 모양을 확대해서 본다."],["짚신벌레 움직임","짚신벌레가 움직이는 현미경 영상 자료를 봤다.","작은 몸이 방향을 바꾸며 물속을 헤엄쳤다.","짚신벌레는 한 세포로 이루어진 원생생물이다.","한 번에 이동한 실제 거리","짚신벌레의 이동 방향과 시간을 기록한다."],["해캄과 짚신벌레","해캄과 짚신벌레의 현미경 모습을 비교했다.","해캄은 실처럼 이어졌고 짚신벌레는 한 개체가 헤엄쳤다.","두 생물은 몸 구조와 생활 방식이 다르다.","각 생물의 실제 유전자 수","현미경 그림으로 둘의 특징을 정리한다."],["해캄 속 엽록체","해캄의 세포를 확대해서 관찰했다.","초록색 부분이 세포 내부에 보였다.","해캄의 엽록체는 빛을 이용한 광합성에 관여한다.","한 세포가 하루 만든 양분량","조명 조건에 따른 해캄의 색과 모습을 살핀다."],["짚신벌레 섬모","짚신벌레의 몸 가장자리를 확대했다.","짧은 털 모양 구조가 많이 있었다.","섬모 움직임은 짚신벌레 이동을 돕는다.","섬모 한 개의 실제 길이","섬모와 이동 방향의 관계를 조사한다."]]],[4,1,"다양한 생물과 우리 생활","세균의 특징은 무엇일까요",[["현미경 속 세균","세균을 확대해 관찰한 사진 자료를 살폈다.","작고 모양이 다른 세균 세포들이 보였다.","세균은 한 세포로 이루어진 미생물이다.","사진 속 모든 세균의 정확한 종류","모양별로 세균 자료를 분류한다."],["요구르트 발효","유산균을 이용하는 발효 식품 제조 과정을 살폈다.","세균이 작용해 식품의 성질이 달라졌다.","일부 세균은 식품 발효에 이용된다.","발효한 식품의 정확한 미생물 수","발효 전후 산도 기록을 비교한다."],["손의 세균","손을 씻기 전과 후의 세균 배양 사진을 비교했다.","손 씻기 뒤 세균 집락이 더 적었다.","올바른 손 씻기는 일부 세균을 제거한다.","모든 세균이 완전히 사라졌는지","안전한 공개 실험 사진으로 비교한다."],["땅속 세균","토양에서 유기물 분해에 관여하는 세균 자료를 읽었다.","세균이 낙엽 등 유기물 분해에 참여했다.","일부 세균은 생태계 물질 순환에 중요하다.","그 토양의 세균 총개체 수","분해 전후 유기물 모습을 살핀다."],["해로운 세균","특정 세균이 사람에게 질병을 일으킬 수 있다는 자료를 읽었다.","세균 가운데 병원성을 가진 종류가 있었다.","모든 세균이 해로운 것은 아니지만 일부는 질병을 일으킨다.","특정 학생이 실제 감염됐는지","유익한 세균과 병원성 세균의 사례를 구분한다."]]],[4,1,"다양한 생물과 우리 생활","다양한 생물이 우리 생활에 미치는 영향을 알아볼까요",[["효모와 빵","효모를 넣은 빵 반죽을 발효시켰다.","반죽이 부풀어 올랐다.","효모는 균류이며 이산화탄소를 만들 수 있다.","발생한 기체의 정확한 질량","효모 유무에 따른 반죽 부피를 비교한다."],["곰팡이와 음식","곰팡이가 핀 음식을 발견했다.","표면의 색과 냄새가 달라졌다.","일부 곰팡이는 음식을 부패시키거나 해로운 물질을 만들 수 있다.","곰팡이의 정확한 독소량","곰팡이 핀 음식은 먹지 않고 안전하게 처리한다."],["세균과 발효","젖산균을 이용해 발효 식품을 만들었다.","발효하며 신맛 등 식품 성질이 달라졌다.","일부 세균은 먹거리를 만드는 데 도움을 준다.","발효한 식품의 정확한 유산균 수","공인된 발효 사례의 변화 자료를 비교한다."],["곤충과 꽃","꽃에 찾아온 벌이 꽃가루를 옮겼다.","꽃가루가 다른 꽃으로 전달됐다.","일부 곤충은 식물 수분에 도움을 준다.","수분으로 생긴 씨앗 전체 수","곤충 방문 전후 꽃의 변화를 기록한다."],["미생물과 분해","나뭇잎이 쌓인 흙에서 분해하는 생물의 역할을 조사했다.","낙엽이 시간이 지나며 잘게 부서지고 분해됐다.","미생물은 자연에서 물질을 되돌리는 데 관여한다.","그 현장의 정확한 세균 종 수","낙엽을 남긴 기간별 모양을 기록한다."]]],[4,1,"다양한 생물과 우리 생활","우리 생활에 생명과학이 이용되는 예를 알아볼까요",[["발효 식품 기술","유산균을 이용해 요구르트를 만드는 과정을 살폈다.","발효 과정에서 식품의 성질이 바뀌었다.","미생물의 성질을 식품 제조에 활용한다.","제품 속 정확한 미생물 수","온도별 발효 기록을 비교한다."],["식물 재배 시설","온실에서 빛·물·온도를 관리하며 채소를 길렀다.","환경을 조절해 식물이 자라도록 했다.","생물의 생장 조건을 농업 기술에 이용한다.","한 포기의 정확한 양분 생산량","생장 조건에 따른 키와 잎 수를 측정한다."],["백신 연구","연구자들이 감염병 예방을 위한 백신의 원리를 설명했다.","몸의 면역반응을 준비하도록 돕는 방법을 연구했다.","생명과학 연구는 질병 예방 기술에 기여한다.","특정 개인의 예방 효과 수치","공신력 있는 예방접종 자료를 확인한다."],["식물 조직 배양","식물의 일부 조직을 깨끗한 배양 환경에서 자라게 했다.","작은 조직에서 새 식물체가 자랄 수 있었다.","식물 세포의 성질을 활용한 번식 기술이다.","모든 식물에서 성공하는지","조직 배양과 씨앗 번식을 비교한다."],["현미경 진단","의료기관에서 미생물의 특징을 검사하는 과정을 조사했다.","검체 속 미생물을 확인하는 검사법이 쓰였다.","생물의 구조와 특징을 질병 진단에 활용한다.","특정 환자의 실제 진단 결과","여러 진단 검사법의 원리를 비교한다."]]],[6,1,"산과 염기","여러 가지 용액을 분류해 볼까요",[["투명한 세 용액","물, 식초, 묽은 베이킹소다 용액을 이름표와 함께 관찰했다.","세 용액이 모두 투명하게 보였다.","용액은 겉모습이 비슷해도 성질이 다를 수 있다.","각 용액의 정확한 pH","안전한 지시약으로 산성·염기성 여부를 조사한다."],["색깔로 분류","붉은 색소가 든 물과 맑은 설탕물을 비교했다.","한 용액만 색이 뚜렷했다.","용액은 색깔처럼 관찰 가능한 특징으로 분류할 수 있다.","설탕물의 정확한 농도","색 이외의 용액 성질도 비교한다."],["가라앉는 고체","소금을 다 녹인 물과 모래가 섞인 물을 관찰했다.","모래 물에서는 바닥에 입자가 남았다.","모든 혼합물이 균일하게 녹은 용액은 아니다.","소금물의 정확한 질량 비율","거르기 전후 두 액체를 비교한다."],["지시약 없는 관찰","식초와 비누를 녹인 물을 안전하게 관찰했다.","겉보기만으로 산성·염기성을 구별하기 어려웠다.","성질 분류에는 알맞은 검사 도구가 필요하다.","각 용액의 수소이온 농도","pH 시험지로 분류하여 기록한다."],["생활용액 이름","식초·설탕물·비눗물을 순서대로 놓았다.","각 용액은 쓰임과 이름이 서로 달랐다.","용액은 구성 물질이나 성질로 분류한다.","용액마다 정확한 점도","성분 표시와 검사 결과를 표로 비교한다."]]],[6,1,"산과 염기","지시약을 이용하여 여러 가지 용액을 분류해 볼까요",[["푸른 리트머스","푸른 리트머스 종이에 묽은 식초를 떨어뜨렸다.","종이의 색이 붉은 쪽으로 변했다.","산성 용액은 푸른 리트머스를 붉게 만들 수 있다.","식초의 정확한 pH 수치","여러 산성 용액을 소량씩 비교한다."],["붉은 리트머스","붉은 리트머스 종이에 묽은 베이킹소다 용액을 묻혔다.","종이가 푸른 쪽으로 변했다.","일부 염기성 용액은 붉은 리트머스를 푸르게 바꾼다.","용액의 정확한 농도","묽은 염기성 용액을 비교한다."],["중성 물","중성에 가까운 물에 리트머스 종이를 각각 넣었다.","붉은 종이와 푸른 종이가 크게 변하지 않았다.","중성 용액은 리트머스 색을 바꾸지 않는다.","물속 무기염류 전체 종류","서로 다른 물 시료의 결과를 비교한다."],["보라색 양배추 지시약","보라색 양배추로 만든 지시약을 식초에 넣었다.","붉거나 분홍색 계열로 변했다.","천연 지시약의 색도 산성도에 따라 달라진다.","양배추 색소의 정확한 농도","산성·중성·염기성 용액의 색을 비교한다."],["pH 시험지","여러 안전한 수용액에 pH 시험지를 묻혔다.","용액마다 서로 다른 색이 나타났다.","시험지의 색을 표준색과 비교하면 산성도를 짐작한다.","용액 속 모든 이온의 양","색상표를 이용해 산성·중성·염기성으로 분류한다."]]],[6,1,"산과 염기","산성 용액과 염기성 용액의 성질을 관찰해 볼까요",[["산성 용액의 지시약","안전하게 묽힌 식초에 푸른 리트머스를 묻혔다.","푸른 종이가 붉게 변했다.","산성 용액은 특정 지시약의 색을 바꾼다.","식초의 정확한 산 농도","다른 산성 용액에서도 시험한다."],["염기성 용액의 지시약","묽은 베이킹소다 용액에 붉은 리트머스를 묻혔다.","붉은 종이가 푸르게 변했다.","염기성 용액도 지시약의 색을 바꾼다.","용액의 정확한 pH 값","다른 안전한 염기성 용액도 비교한다."],["달걀껍데기와 식초","달걀껍데기 조각에 식초를 조금 떨어뜨렸다.","껍데기 표면에서 기포가 발생했다.","산성 식초와 탄산칼슘의 반응으로 기체가 나온다.","발생한 이산화탄소의 정확한 질량","식초 대신 물을 넣어 결과를 비교한다."],["철과 묽은 산","교사가 통제된 실험으로 철과 묽은 산의 반응을 보여줬다.","철 표면에 작은 기포가 나타날 수 있었다.","일부 금속은 산과 반응하여 수소 기체를 만든다.","발생한 기체의 정확한 부피","안전 규칙을 지키며 금속 종류별 자료를 비교한다."],["안전하게 다루기","성질을 알 수 없는 용액을 관찰했다.","학생들은 맛이나 맨손 접촉으로 성질을 판단하지 않았다.","산·염기 실험은 지시약과 보호 장비를 이용해야 한다.","용액의 실제 성분","교사의 안내 아래 지시약으로 확인한다."]]],[6,1,"산과 염기","산성 용액과 염기성 용액을 섞으면 어떻게 될까요",[["산과 염기 혼합","묽은 산성 용액에 묽은 염기성 용액을 조금씩 더하며 pH를 기록했다.","pH 값이 중성에 가까워지는 구간이 관찰됐다.","산성과 염기성 용액을 알맞게 섞으면 중화 반응이 일어날 수 있다.","정확한 반응열","pH 변화를 단계별로 기록한다."],["염기 더하기","같은 산성 용액에 염기성 용액을 조금 더 많이 넣었다.","처음보다 산성이 약해진 것으로 측정됐다.","염기를 추가하면 중화가 진행될 수 있다.","중화점에서의 정확한 염 농도","넣은 용액의 양과 pH를 표로 정리한다."],["많이 넣은 염기","산에 염기를 많이 넣어 중화점을 넘긴 경우를 모형으로 살폈다.","최종 용액이 염기성을 나타낼 수 있었다.","중화가 일어나도 항상 최종 용액이 중성인 것은 아니다.","최종 용액의 정확한 이온 조성","넣은 양을 달리해 지시약 색을 비교한다."],["온도 상승","묽은 산과 염기가 반응하는 안전한 시연에서 온도 변화를 측정했다.","혼합액의 온도가 조금 올라갔다.","일부 중화 반응은 열을 방출한다.","발생한 열량의 정확한 값","온도계를 이용해 혼합 전후 온도를 기록한다."],["안전한 실험","산성·염기성 용액을 다룰 때 교사의 지시에 따라 보호 장비를 착용했다.","위험한 고농도 용액은 사용하지 않았다.","화학 변화 실험은 알맞은 안전 수칙이 중요하다.","미지 용액의 정확한 성분","지시약만 사용한 안전한 비교 활동을 실시한다."]]],[6,1,"산과 염기","산성 용액과 염기성 용액을 이용하는 예를 알아볼까요",[["식초와 음식","음식 조리에 식초를 적은 양 사용했다.","식초가 음식의 산미를 더했다.","식초 속 아세트산은 산성 성질을 갖는다.","음식의 정확한 산도","식초를 넣기 전후 pH 자료를 조사한다."],["제빵용 소다","빵 반죽에 베이킹소다를 사용하는 조리법을 살펴봤다.","반죽을 부풀게 하는 데 쓰일 수 있었다.","베이킹소다는 염기성을 띠고 산성 성분과 반응하면 기체를 낸다.","발생한 기체의 정확한 질량","베이킹소다와 산성 재료의 반응을 자료로 비교한다."],["세정용 비누","비누를 물에 녹인 용액의 성질을 지시약으로 살폈다.","일반적인 비누 용액이 염기성을 나타냈다.","일부 세정 용품은 염기성 성질을 활용한다.","비누의 정확한 제조 성분 비율","용품 표시와 지시약 색을 비교한다."],["제산제의 기능","위산을 중화하는 제산제 설명서를 살펴봤다.","일부 제산제가 위 속 산을 중화하는 데 쓰였다.","적절한 염기성 성분은 산을 중화하는 데 이용된다.","개인의 위산 농도","의약품 설명서의 성분과 목적을 확인한다."],["안전한 세척","서로 다른 세정제를 함께 섞지 말라는 표기를 읽었다.","성분을 모르고 용액을 혼합하지 않았다.","산성과 염기성의 성질을 안다고 세정제를 임의로 혼합하면 안 된다.","임의 혼합의 발생 기체 종류","제품별 안전 표시를 먼저 조사한다."]]],[6,1,"물체의 운동","물체의 운동을 알아볼까요",[["걸어가는 학생","운동장 기준선에서 학생이 앞으로 걸어갔다.","기준선에서 학생의 위치가 달라졌다.","운동은 시간에 따라 위치가 변하는 것이다.","이동한 정확한 전체 거리","시각별 위치를 같은 기준으로 기록한다."],["정지한 의자","교실 바닥을 기준으로 의자를 관찰했다.","의자의 위치가 일정하게 유지됐다.","기준에 대한 위치가 변하지 않으면 정지로 본다.","의자의 질량","시간을 바꿔 같은 기준에서 관찰한다."],["움직이는 버스","정류장 표지판을 기준으로 출발한 버스를 관찰했다.","버스가 정류장에서 멀어졌다.","운동을 판단할 때 기준 물체를 정해야 한다.","버스 엔진의 정확한 출력","다른 정류장을 기준으로 위치를 기록한다."],["움직이는 시계침","시계 중심을 기준으로 초침 끝을 관찰했다.","초침 끝 위치가 시간이 지나며 달라졌다.","직선이 아닌 원 모양의 운동도 있다.","초침의 실제 질량","5초마다 초침 끝의 위치를 표시한다."],["흐르는 물","강변 바위를 기준으로 잎 조각이 움직이는 모습을 봤다.","잎이 바위에서 점점 멀어졌다.","물 흐름에 따라 물체의 위치가 변할 수 있다.","잎의 정확한 부피","일정 시간마다 잎의 위치를 표시한다."]]],[6,1,"물체의 운동","물체의 운동은 어떻게 표현할까요",[["5초마다 위치","장난감 차가 0초에 0 m, 5초에 2 m, 10초에 4 m 지점에 있었다.","같은 5초 간격마다 2 m씩 이동했다.","운동은 시간별 위치 변화로 표현할 수 있다.","자동차의 실제 무게","시간과 위치를 표로 그려 본다."],["출발과 도착","학생이 운동장 출발점에서 10 m 떨어진 나무까지 걸었다.","출발점과 도착점의 위치가 달랐다.","이동한 거리와 이동 시간을 함께 기록할 수 있다.","학생이 소비한 열량","걸린 시간을 초 단위로 재어 기록한다."],["굽은 길","자전거가 곡선 도로를 따라 움직였다.","이동하는 동안 방향이 계속 달라졌다.","물체의 운동은 이동 경로와 방향도 포함한다.","자전거의 정확한 구동력","바퀴 자국을 따라 경로를 그린다."],["한자리에 머물기","멈춰 있는 공을 일정 시간마다 같은 곳에서 관찰했다.","공의 위치가 변하지 않았다.","운동 여부는 기준 위치와 시간으로 표현한다.","공의 속 내부 구조","기준선을 표시하여 위치 변화를 살핀다."],["걷는 거리 표","가 학생은 20초 동안 20 m, 나 학생은 20초 동안 30 m 걸었다.","같은 시간에 나 학생이 더 멀리 이동했다.","시간과 거리를 함께 비교하면 운동의 빠르기를 짐작할 수 있다.","두 학생의 정확한 심박수","같은 시간 동안 이동 거리를 반복 측정한다."]]],[6,1,"물체의 운동","같은 시간 동안 이동한 물체의 빠르기를 비교해 볼까요",[["두 학생 달리기","가 학생은 10초 동안 20 m, 나 학생은 10초 동안 30 m 뛰었다.","같은 10초에 나 학생이 10 m 더 이동했다.","같은 시간에는 더 먼 거리를 움직인 물체가 빠르다.","각 학생의 실제 가속도","같은 출발 시간으로 여러 번 거리 비교를 한다."],["장난감 자동차","같은 시간 5초 동안 두 장난감 차가 각각 2 m와 3 m 이동했다.","3 m 간 차가 더 멀리 움직였다.","시간이 같을 때 이동 거리로 빠르기를 비교한다.","두 차의 실제 질량","5초마다 도달한 위치를 다시 측정한다."],["두 자전거","두 자전거를 같은 길에서 20초 동안 이동시켰다.","가 자전거 60 m, 나 자전거 80 m를 이동했다.","같은 시간에 더 긴 거리를 간 나 자전거가 빠르다.","두 자전거의 정확한 바퀴 지름","시간을 고정하여 거리 측정을 반복한다."],["두 거북 모형","작동하는 두 거북 모형을 같은 1분 동안 움직였다.","가 모형은 40 cm, 나 모형은 60 cm 이동했다.","같은 시간에 더 긴 거리를 이동하면 더 빠르다.","모형의 실제 배터리 용량","이동 거리를 줄자로 재어 비교한다."],["멈춘 물체 포함","가 공은 5초간 0 m, 나 공은 5초간 1 m 움직였다.","나 공만 출발점에서 멀어졌다.","이동 거리 0인 물체는 그 시간에 정지한 것으로 본다.","공의 정확한 탄성","같은 위치에서 시간을 늘려 관찰한다."]]],[6,1,"물체의 운동","물체의 속력은 어떻게 구할까요",[["100 m 달리기","가 학생이 100 m를 20초에 달렸다.","이동 거리와 시간은 100 m와 20초였다.","속력은 이동 거리를 걸린 시간으로 나누어 구한다.","달리는 동안의 순간 최고속력","100÷20으로 평균 속력을 계산한다."],["자전거 주행","자전거가 200 m를 40초 동안 일정하게 이동했다.","40초에 200 m를 이동했다.","평균 속력은 거리 200 m를 시간 40초로 나누어 구한다.","자전거의 실제 페달 회전수","거리와 시간을 표로 기록해 속력을 계산한다."],["장난감 차","모형 차가 12 m를 6초에 이동했다.","6초 동안 12 m를 움직였다.","평균 속력은 12÷6으로 2 m/s다.","차가 가속한 정확한 구간","같은 차가 다른 거리에서 걸리는 시간을 잰다."],["걷는 학생","한 학생이 60 m를 30초 동안 걸었다.","30초 동안 60 m를 이동했다.","평균 속력은 2 m/s로 계산된다.","학생의 실제 최대 속력","60 m 거리를 여러 번 걸어 시간을 비교한다."],["표의 단위","물체가 1분 동안 120 m를 이동했다.","60초 동안 120 m 움직였다.","1분을 60초로 바꾸면 평균 속력은 2 m/s다.","속력의 시간별 변화","시간 단위를 바꾸어 두 방법의 값을 비교한다."]]],[6,1,"물체의 운동","물체의 빠르기를 속력으로 비교해 볼까요",[["빠른 자전거","가 자전거는 100 m를 20초, 나 자전거는 100 m를 25초에 이동했다.","같은 거리를 가 자전거가 5초 더 빨리 끝냈다.","거리가 같으면 시간이 짧은 쪽 평균 속력이 높다.","두 자전거의 실제 모터 출력","거리÷시간으로 두 속력을 비교한다."],["단위 비교","가 물체는 2 m/s, 나 물체는 3 m/s로 기록했다.","나 물체가 1초에 평균 1 m 더 이동한다.","같은 단위로 표시된 속력은 수치 크기로 비교한다.","각 물체의 정확한 무게","같은 5초 동안 거리를 계산해 비교한다."],["시간과 거리","가 모형은 20 m를 10초, 나 모형은 30 m를 10초에 이동했다.","가와 나의 평균 속력은 각각 2 m/s와 3 m/s였다.","같은 시간에는 더 먼 거리를 가는 쪽의 속력이 높다.","두 모형의 정지 시간 포함 여부","반복해서 시간·거리 기록을 비교한다."],["걷기와 뛰기","한 학생이 걸어서 50 m를 50초에, 뛰어서 50 m를 10초에 이동했다.","뛰었을 때 걸린 시간이 짧았다.","같은 거리를 짧은 시간에 이동하면 평균 속력이 크다.","학생의 실제 칼로리 소모량","걷기와 뛰기의 거리·시간을 측정한다."],["미터와 킬로미터","가 자동차는 시속 36 km, 나 자전거는 초속 5 m로 달렸다.","36 km/h는 10 m/s로 바꿀 수 있다.","단위가 다를 때는 같은 단위로 바꿔 속력을 비교해야 한다.","자동차의 실제 연료 사용량","36÷3.6과 5의 크기를 비교한다."]]],[6,1,"식물의 구조와 기능","식물을 이루는 세포를 관찰해 볼까요",[["양파 표피","양파 표피를 얇게 준비한 현미경 표본을 살폈다.","작은 칸처럼 보이는 세포들이 나란히 있었다.","식물의 몸은 세포로 이루어져 있다.","세포마다 실제 질량","확대 배율을 바꿔 세포 모양을 비교한다."],["식물 세포의 벽","식물의 세포 사진에서 세포의 바깥 경계를 살폈다.","세포마다 비교적 뚜렷한 바깥 벽이 보였다.","식물 세포에는 세포벽이 있다.","세포벽의 정확한 두께","식물과 동물의 세포 모형을 비교한다."],["잎의 세포","잎의 현미경 사진에서 초록색 부분을 관찰했다.","일부 세포에 엽록체가 많이 보였다.","광합성을 하는 식물 세포에는 엽록체가 있다.","세포당 실제 광합성 속도","빛 조건에 따라 엽록체 관찰 자료를 비교한다."],["세포 크기 비교","양파 표피와 잎의 세포를 같은 배율 사진으로 비교했다.","세포마다 모양과 크기가 달랐다.","같은 식물 안에도 역할에 따라 세포 특징이 달라질 수 있다.","모든 세포의 정확한 기능","서로 다른 식물 조직의 세포 모양을 기록한다."],["핵을 볼 수 있는 표본","안전하게 염색된 식물 세포 사진을 관찰했다.","세포 안에 핵으로 보이는 부분이 있었다.","세포 내부에는 여러 구조가 존재한다.","각 세포의 실제 DNA 양","핵과 세포벽 위치를 그림으로 나타낸다."]]],[6,1,"식물의 구조와 기능","뿌리의 구조와 기능을 알아볼까요",[["뿌리털","뿌리 끝부분을 확대해서 관찰했다.","표면에 가늘고 작은 뿌리털이 많이 보였다.","뿌리털은 물과 무기 양분 흡수를 돕는다.","뿌리털 하나의 실제 흡수량","뿌리털이 많은 부분을 비교한다."],["흙을 붙잡는 뿌리","바람이 불어도 나무가 쓰러지지 않는 이유를 살폈다.","여러 뿌리가 땅속으로 퍼져 있었다.","뿌리는 식물 몸을 지탱하는 역할도 한다.","그 나무가 견디는 최대 바람 세기","뿌리 뻗은 방향을 그림으로 표시한다."],["뿌리에서 물 이동","화분에 물을 주고 식물 상태를 관찰했다.","시든 잎이 시간이 지나 조금 펴졌다.","뿌리로 흡수한 물이 줄기를 따라 이동할 수 있다.","이동한 정확한 물의 질량","물 주기 전후 줄기와 잎 상태를 기록한다."],["무의 뿌리","무를 관찰하니 땅속 부분이 두껍게 발달했다.","굵은 뿌리에 양분이 저장되어 있었다.","일부 식물의 뿌리는 양분을 저장한다.","저장된 양분의 정확한 질량","무와 당근의 뿌리 모양을 비교한다."],["콩 뿌리","강낭콩의 어린 뿌리를 관찰했다.","주된 뿌리에서 가는 곁뿌리가 갈라졌다.","뿌리가 가지처럼 분포하며 땅속 물을 흡수한다.","뿌리 끝의 정확한 생장 속력","같은 식물의 뿌리를 날짜별로 기록한다."]]],[6,1,"식물의 구조와 기능","줄기의 구조와 기능을 알아볼까요",[["색 물의 이동","흰 꽃이 달린 줄기를 색소가 든 물에 꽂았다.","시간이 지나 꽃잎 일부에 색이 나타났다.","줄기 속 물 이동 통로가 뿌리 쪽에서 위로 이어진다.","한 시간 동안 움직인 물의 정확한 양","줄기 단면을 관찰해 색소 경로를 살핀다."],["나무줄기 단면","나무줄기 단면 모형을 관찰했다.","안쪽에 서로 다른 조직이 층을 이루었다.","줄기에는 물질을 이동시키는 조직이 있다.","조직별 정확한 세포 수","식물 줄기 단면 사진을 서로 비교한다."],["넝쿨 줄기","울타리를 감고 자라는 덩굴 식물을 관찰했다.","줄기가 지지물을 따라 구부러져 올라갔다.","줄기는 잎을 받쳐 주고 식물의 형태를 유지한다.","줄기에서 발생한 정확한 힘","지지물이 없을 때 자람을 비교한다."],["사막 선인장","선인장의 굵은 초록 줄기를 관찰했다.","두꺼운 줄기에 물이 저장될 수 있었다.","일부 식물은 줄기에서 물을 저장하거나 광합성한다.","선인장 줄기의 실제 수분 비율","다른 식물 줄기와 두께를 비교한다."],["줄기 꺾임","어린 식물 줄기를 지지대로 받쳐 준 자료를 보았다.","지지대를 댄 줄기가 넘어지지 않았다.","줄기는 식물 몸을 세우고 잎을 지탱한다.","그 줄기의 정확한 강도","줄기 굵기별 지탱 모습을 비교한다."]]],[6,1,"식물의 구조와 기능","잎의 구조와 잎에서 만드는 양분을 알아볼까요",[["햇빛 받은 잎","같은 식물의 잎을 빛과 어둠 조건에서 관찰했다.","빛을 받은 잎에서 녹말 검사가 양성을 보일 수 있었다.","광합성은 빛 에너지를 이용해 양분을 만드는 과정이다.","잎의 정확한 포도당 생산량","빛의 유무만 달리한 검사를 비교한다."],["잎의 기공","잎 표피를 확대해서 관찰했다.","작은 틈 모양의 기공이 보였다.","기공은 기체 교환과 물의 증산에 관련된다.","기공 하나의 실제 개폐력","잎의 윗면과 아랫면 기공을 비교한다."],["엽록체","잎 세포의 초록색 구조를 살폈다.","엽록체가 여러 개 보였다.","엽록체는 식물의 광합성에 관여한다.","엽록체마다 정확한 엽록소량","잎 색이 다른 부위의 세포를 비교한다."],["물과 이산화탄소","빛을 받은 식물이 광합성을 하는 모형을 살폈다.","물과 이산화탄소를 이용해 양분을 만든다고 나타났다.","식물은 광합성에 물과 이산화탄소가 필요하다.","실제 식물의 하루 광합성량","물·빛 조건을 달리한 생장 자료를 조사한다."],["빛 부족한 잎","빛이 부족한 장소에 둔 식물의 잎을 관찰했다.","잎의 생장과 색이 달라졌다.","빛 조건은 잎의 양분 생산과 성장에 영향을 준다.","잎이 가진 정확한 녹말 질량","빛의 양에 따라 녹말 검사 자료를 비교한다."]]],[6,1,"식물의 구조와 기능","잎에 도달한 물은 어떻게 될까요",[["비닐 봉지 씌운 잎","잎이 달린 가지에 투명한 비닐을 묶고 햇빛에 두었다.","비닐 안쪽에 작은 물방울이 생겼다.","잎에서 나온 수증기가 비닐 안쪽에 응결할 수 있다.","실제 증산한 물의 질량","잎이 없는 가지와 비교한다."],["기공과 물","잎의 기공 모형을 관찰했다.","잎 표면에 작은 기공이 있었다.","잎의 기공은 증산이 일어나는 중요한 통로다.","한 기공을 통과한 정확한 수증기량","기공 개폐 조건과 증산량을 비교한다."],["바람과 증산","같은 식물 잎에 바람이 부는 조건과 없는 조건을 비교했다.","바람이 있는 조건에서 물 손실이 늘 수 있었다.","바람은 잎 주변 습한 공기를 이동시켜 증산에 영향을 준다.","실제 기공이 열린 개수","바람만 바꿔 잎 무게 변화를 잰다."],["건조한 공기","같은 잎을 습한 장소와 건조한 장소에서 비교했다.","건조한 쪽에서 물이 더 빨리 빠질 수 있었다.","공기 습도는 증산 속도에 영향을 준다.","잎의 정확한 수분 퍼센트","습도만 조절해 물 손실을 측정한다."],["물이 이동한 줄기","뿌리에서 물을 흡수한 식물의 줄기와 잎을 관찰했다.","물의 일부가 잎에서 수증기로 나갔다.","증산은 물이 뿌리에서 잎까지 이동하는 데 도움을 준다.","물 분자 한 개의 이동 시간","뿌리 흡수량과 잎 물 손실량을 함께 관찰한다."]]],[6,1,"식물의 구조와 기능","꽃의 구조와 기능을 알아볼까요",[["꽃잎과 꽃받침","꽃의 바깥 부분을 관찰했다.","꽃잎과 꽃받침의 위치가 구별됐다.","꽃잎은 수분매개자를 끌어들이고 꽃받침은 꽃봉오리를 보호한다.","꽃잎의 정확한 색소 농도","꽃받침과 꽃잎의 모양을 비교한다."],["수술의 꽃가루","꽃의 수술 끝을 확대했다.","꽃밥 부근에 꽃가루가 있었다.","수술은 꽃가루를 만드는 생식 구조다.","꽃밥에 든 꽃가루의 정확한 개수","여러 꽃에서 꽃가루 위치를 비교한다."],["암술의 구조","꽃 가운데 암술을 관찰했다.","암술머리와 아래의 씨방을 볼 수 있었다.","암술에는 꽃가루를 받는 부분과 밑씨가 있는 부분이 있다.","밑씨 하나의 정확한 질량","꽃의 암술과 수술 위치를 그림으로 표시한다."],["수분의 과정","곤충이 꽃에 앉아 다른 꽃으로 이동했다.","꽃가루가 다른 꽃의 암술머리에 옮겨질 수 있었다.","수분은 꽃가루가 암술머리에 닿는 과정이다.","전달된 꽃가루의 정확한 수","꽃가루가 옮겨지는 경로를 모형으로 살핀다."],["씨와 열매","수분과 수정이 이뤄진 꽃이 시간이 지나 변했다.","씨방이 자라 열매가 되고 밑씨는 씨가 될 수 있었다.","꽃의 생식 구조는 씨와 열매 형성에 관여한다.","형성된 씨의 정확한 개수","꽃과 어린 열매 모습을 시기별로 비교한다."]]],[6,1,"식물의 구조와 기능","식물의 각 기관이 어떻게 관련되어 있을까요",[["뿌리와 잎 연결","물 흡수와 광합성 모형을 함께 살폈다.","뿌리에서 흡수한 물이 줄기를 지나 잎으로 이동했다.","뿌리·줄기·잎은 물질 이동으로 연결된다.","하루 동안 물의 전체 이동량","각 기관의 물 이동 방향을 도식으로 그린다."],["잎에서 만든 양분","햇빛을 받은 식물이 양분을 만든다는 자료를 읽었다.","잎에서 만들어진 당이 다른 기관에도 이동했다.","광합성 산물은 생장과 저장 등에 이용될 수 있다.","뿌리에 도달한 정확한 당의 질량","줄기의 물관과 체관 역할을 비교한다."],["꽃과 잎","꽃이 핀 식물에서 잎과 꽃을 함께 관찰했다.","잎이 있고 꽃에서 씨를 만드는 과정이 진행됐다.","잎의 양분 생산은 꽃과 씨의 성장에도 도움 된다.","그 꽃에 쓰인 양분의 정확한 양","꽃이 피기 전후 잎·줄기 변화를 기록한다."],["뿌리와 꽃","뿌리가 손상된 식물의 생장 자료를 살폈다.","물 흡수에 문제가 생기면 지상부 상태도 나빠질 수 있었다.","하나의 기관 상태가 다른 기관에도 영향을 줄 수 있다.","손상된 뿌리의 세포 수","뿌리 상태별 줄기·꽃 생장을 비교한다."],["기관 역할 표","뿌리·줄기·잎·꽃의 기능을 표로 정리했다.","각 기관마다 하는 일이 달랐다.","식물의 여러 기관은 서로 다른 일을 하며 협력한다.","기관마다 하루 사용한 에너지양","물과 양분의 이동 경로를 연결한다."]]],[6,1,"지구의 운동","하루 동안 태양과 별의 위치는 어떻게 달라질까요",[["아침과 오후 태양","같은 장소에서 오전 9시와 오후 3시에 태양 위치를 관찰했다.","태양의 하늘 위치가 달라져 보였다.","지구 자전에 따라 태양은 하루 동안 이동하는 듯 보인다.","태양의 실제 공간 이동 거리","같은 장소에서 시각별 방향을 기록한다."],["낮의 그림자","막대를 같은 자리에 세워 아침과 낮 그림자를 관찰했다.","그림자 길이와 방향이 시간에 따라 바뀌었다.","태양의 겉보기 위치가 달라져 그림자가 변한다.","막대가 받은 실제 복사 에너지","매시간 그림자 길이를 비교한다."],["밤의 북두칠성","북두칠성의 위치를 저녁과 밤늦게 비교했다.","별자리의 방향과 높이가 달라 보였다.","지구 자전 때문에 별은 밤하늘에서 움직이는 듯 보인다.","각 별의 실제 공전 속력","같은 시각과 장소에서 별 위치를 기록한다."],["태양의 방향","맑은 날 오전과 오후에 태양을 안전하게 간접 관찰했다.","태양이 동쪽 하늘에서 서쪽 하늘로 이동하는 듯 보였다.","태양의 일주운동은 지구 자전의 결과다.","지구가 그날 이동한 공전 거리","태양 관찰 기구로 그림자의 방향을 기록한다."],["밤하늘 사진","같은 위치에서 시간 간격을 두고 별을 촬영한 자료를 비교했다.","별이 하늘에서 위치를 바꾼 것으로 기록됐다.","별의 겉보기 위치 변화는 지구 자전과 관계된다.","각 별이 지구에서 얼마나 떨어졌는지","시간별 별의 위치를 겹쳐 표시한다."]]],[6,1,"지구의 운동","지구의 자전은 무엇일까요",[["지구본 회전","지구본을 기울인 축을 중심으로 돌렸다.","같은 지점이 회전하며 앞뒤 방향을 바꾸었다.","지구 자전은 지구가 자전축을 중심으로 도는 운동이다.","지구본 내부의 실제 질량","지구본 한 바퀴 도는 방향을 기록한다."],["하루의 길이","지구가 자전축 주위를 거의 하루에 한 바퀴 돈다는 자료를 읽었다.","지구는 주기적으로 한 번씩 회전했다.","지구 자전은 낮과 밤의 주기와 연결된다.","지구 표면의 정확한 바람 속력","자전 주기와 낮밤 변화 모형을 비교한다."],["동쪽으로 자전","북극 위에서 내려다보는 모형에서 지구를 반시계 방향으로 돌렸다.","모형이 서쪽에서 동쪽으로 회전했다.","지구 자전의 기본 방향은 서쪽에서 동쪽이다.","자전으로 적도가 움직이는 정확한 속력","표면 점을 표시해 이동 방향을 살핀다."],["자전과 별의 움직임","지구가 회전하는 모형 옆에 고정된 별 그림을 놓았다.","지구본 위 관찰자가 보는 별 방향이 달라졌다.","지구가 돌아 별이 움직이는 것처럼 보인다.","그 별의 실제 광도","자전 모형에서 별 위치를 여러 시각에 비교한다."],["자전축","지구본의 북극과 남극을 지나는 축을 따라 회전시켰다.","극 부근의 축이 회전 기준이 되었다.","지구는 남북극을 잇는 자전축을 중심으로 돈다.","지구 자전축의 정확한 기울기 측정값","축과 적도의 방향을 모형으로 구별한다."]]],[6,1,"지구의 운동","낮과 밤이 생기는 까닭은 무엇일까요",[["손전등과 지구본","어두운 곳에서 손전등으로 지구본 한쪽을 비췄다.","빛을 받는 쪽은 밝고 뒤쪽은 어두웠다.","태양을 향한 쪽이 낮이고 반대쪽이 밤이다.","실제 지구의 구름 분포","모형 지구를 돌려 밝은 부분의 변화를 살핀다."],["자전하는 지구본","한 지점 표시가 있는 지구본을 고정된 손전등 앞에서 돌렸다.","표시가 밝은 곳과 어두운 곳을 번갈아 지났다.","지구 자전으로 낮과 밤이 번갈아 나타난다.","그 지점의 실제 일출 시각","표시가 빛을 받는 시간 변화를 기록한다."],["같은 시각의 두 나라","지구본 양쪽에 위치한 두 지역을 손전등 모형으로 살펴봤다.","한쪽은 밝고 다른 쪽은 어두웠다.","지구의 서로 다른 곳은 같은 때 낮과 밤이 다를 수 있다.","각 나라의 정확한 현지 시각","지역 위치를 옮겨 낮밤을 표시한다."],["고정된 공전 모형","지구본을 돌리지 않고 태양빛 모형만 비췄다.","같은 지점은 계속 밝거나 어두운 쪽에 머물렀다.","자전하지 않으면 일상적인 낮밤 교대가 나타나지 않는다.","모형의 실제 밝기 수치","회전 유무만 달리해 밝음 변화를 비교한다."],["해 뜨는 방향","지구의 자전 모형에서 한 지점의 아침을 살폈다.","태양이 동쪽에서 떠오르는 듯 보였다.","태양의 겉보기 일주운동은 자전 때문에 나타난다.","그날의 정확한 낮 길이","여러 위도에서 해 뜨는 방향을 비교한다."]]],[6,1,"지구의 운동","지구의 공전은 무엇일까요",[["태양 주위의 모형","태양 모형을 가운데 두고 지구본을 주위로 움직였다.","지구 모형의 태양에 대한 위치가 달라졌다.","지구 공전은 지구가 태양 주위를 도는 운동이다.","공전 궤도의 실제 길이","모형에서 한 바퀴 도는 경로를 표시한다."],["일 년의 반복","지구가 태양 둘레를 약 1년에 한 바퀴 공전한다는 자료를 읽었다.","공전 위치가 1년을 주기로 다시 비슷해졌다.","공전 주기는 달력의 한 해와 관련된다.","매년 공전 경로의 정확한 차이","월별 지구 공전 위치를 기록한다."],["자전과 공전","지구본을 축을 중심으로 돌리면서 태양 모형 주위도 이동시켰다.","회전하는 운동과 궤도를 따라 이동하는 운동이 함께 보였다.","지구는 자전과 공전을 동시에 한다.","실제 태양의 정확한 질량","두 운동의 경로를 다른 색으로 표시한다."],["지구 궤도","태양 주변의 지구 공전 경로를 위에서 본 모형을 살폈다.","지구가 태양을 중심으로 닫힌 경로를 따라 이동했다.","지구의 공전 궤도는 원에 가까운 타원이다.","지구와 태양의 실제 최단 거리","공전 경로를 모형으로 그려 비교한다."],["공전과 밤하늘","서로 다른 달에 밤하늘을 보는 지구 위치 모형을 비교했다.","태양 반대쪽 하늘의 방향이 달라졌다.","지구 공전으로 밤에 보이는 별자리도 달라질 수 있다.","각 별의 실제 나이","계절별 관찰 방향을 모형으로 표시한다."]]],[6,1,"지구의 운동","계절별 대표적인 별자리에는 어떤 것이 있을까요",[["봄의 북쪽 하늘","봄철 저녁 하늘의 별자리 자료를 살폈다.","사자자리와 목동자리 등이 봄 하늘에서 잘 보였다.","계절마다 대표적으로 관찰하는 별자리가 있다.","별 하나의 정확한 밝기","봄 저녁 별자리 지도를 관찰한다."],["여름의 별","여름 저녁 남쪽 하늘을 살펴본 기록을 읽었다.","백조자리·거문고자리·독수리자리 주변 밝은 별이 눈에 띄었다.","여름철의 별자리와 여름철 대삼각형을 찾아볼 수 있다.","별의 실제 표면 온도","여름 별지도를 통해 세 밝은 별을 찾아본다."],["가을 별자리","가을 밤하늘의 별지도를 살폈다.","페가수스자리의 큰 사각형 모양이 보였다.","가을의 대표적인 별자리 배치를 찾을 수 있다.","페가수스자리의 실제 거리","가을 별지도의 사각형 주변 별을 표시한다."],["겨울의 오리온","겨울 저녁 하늘의 오리온자리를 관찰했다.","가운데 세 별이 나란히 놓인 모양이 보였다.","오리온자리는 겨울철에 눈에 띄는 대표 별자리다.","오리온자리 각 별의 정확한 질량","별 세 개의 위치를 별지도로 확인한다."],["계절별 별지도","같은 시각 봄과 겨울에 보이는 하늘 자료를 비교했다.","대표적으로 보이는 별자리가 달랐다.","계절에 따라 밤에 바라보는 우주 방향이 달라진다.","별자리 전체의 실제 별 개수","계절별 하늘 지도를 겹쳐 비교한다."]]],[6,1,"지구의 운동","계절별 대표적인 별자리가 달라지는 까닭은 무엇일까요",[["봄과 가을 위치","지구 공전 궤도의 서로 다른 계절 위치를 비교했다.","지구에서 태양 반대쪽을 보는 방향이 달랐다.","공전 때문에 계절별 밤하늘 방향이 달라진다.","별이 실제로 움직인 정확한 거리","공전 위치마다 밤쪽 관찰 방향을 그린다."],["고정된 별 모형","별 모형을 고정하고 지구 모형만 태양 주위로 이동시켰다.","지구 모형에서 보는 별의 방향이 달라졌다.","별이 크게 이동하지 않아도 공전 때문에 보임이 달라진다.","실제 별 사이 거리","지구 위치를 바꿔 관찰 범위를 기록한다."],["태양 반대편","밤하늘을 관찰하는 방향을 태양 반대쪽으로 표시했다.","계절에 따라 서로 다른 별 영역이 밤쪽에 놓였다.","밤에 보이는 별자리는 공전 위치와 관계된다.","관찰지의 정확한 위도","월별 태양 반대쪽 방향을 표기한다."],["일 년 주기","지구가 태양 주위를 한 바퀴 돈 뒤 하늘 모형을 다시 살폈다.","비슷한 계절에 비슷한 별자리 배치가 나타났다.","계절별 별자리는 해마다 비슷한 시기에 되풀이된다.","해마다 별의 고유운동 수치","같은 날짜와 시각의 별지도 여러 해를 비교한다."],["자전과 공전 구별","하루 동안 별의 위치와 계절별 대표 별자리를 따로 비교했다.","하루 안의 이동과 계절에 따른 별자리 종류 변화가 달랐다.","자전은 일주운동을, 공전은 계절별 관찰 방향 변화를 주로 설명한다.","해당 별의 실제 광도","일별 위치 자료와 계절별 별지도를 구분한다."]]]];
function register({bank}){
 const list=[];
 const prompts=[
  ['「%s」 관찰 기록에 실제로 나타난 것은 무엇인가요?','「%s」에서 확인된 변화는 무엇인가요?','「%s」의 결과를 제대로 읽은 것은 무엇인가요?','「%s」에서 직접 관찰한 내용은 무엇인가요?','「%s」의 측정·관찰 결과는 무엇인가요?'],
  ['「%s」 결과를 과학적으로 설명하면 무엇인가요?','「%s」와 관련된 성질은 무엇인가요?','「%s」 자료를 뒷받침하는 설명은 무엇인가요?','「%s」에서 나타난 원리로 알맞은 것은 무엇인가요?','「%s」에서 얻을 수 있는 결론은 무엇인가요?'],
  ['「%s」의 실험 조건이나 조사 상황은 무엇인가요?','「%s」 자료가 관찰한 조건은 무엇인가요?','「%s」에서 비교한 상태는 무엇인가요?','「%s」에서 바꾸거나 살펴본 조건은 무엇인가요?','「%s」의 관찰 환경으로 맞는 것은 무엇인가요?'],
  ['「%s」에서 기록하지 않은 내용은 무엇인가요?','「%s」 자료만으로 확인할 수 없는 것은 무엇인가요?','「%s」 기록의 한계로 맞는 것은 무엇인가요?','「%s」에서 추가 확인이 필요한 정보는 무엇인가요?','「%s」 자료에 없는 값이나 사실은 무엇인가요?'],
  ['「%s」 자료를 보완할 탐구는 무엇인가요?','「%s」에 이어 살펴볼 활동으로 알맞은 것은 무엇인가요?','「%s」에서 더 알아보는 방법은 무엇인가요?','「%s」의 결과를 확인할 추가 관찰은 무엇인가요?','「%s」에서 직접 조사할 만한 다음 단계는 무엇인가요?']
 ];
 for(const [grade,semester,unit,lesson,caseRows] of LESSONS){
  if(caseRows.length!==5)throw Error('Need 5 source cases '+grade+'-'+semester+' '+lesson);
  const rows=[],id='science-rework-'+grade+'-'+semester+'-'+list.length;
  for(let i=0;i<caseRows.length;i++){
   const [title,condition,observation,principle,unknown,next]=caseRows[i];
   if([title,condition,observation,principle,unknown,next].some((v,index)=>typeof v!=='string'||v.length<(index===0?2:6)))throw Error('Incomplete source '+lesson+' '+title);
   const detail='[관찰 자료 · '+title+'] '+condition+' '+observation+' 이 관찰은 '+principle+'';
   const answers=[observation,principle,condition,unknown,next];
   for(let j=0;j<5;j++){
    const options=j===3?[observation,condition]:caseRows.filter((_,k)=>k!==i).map(c=>c[[2,3,1,4,5][j]]).filter(x=>x!==answers[j]);
    const wrong=[...new Set(options)].slice(0,2);
    if(wrong.length!==2)throw Error('Duplicate evidence choices '+lesson+' '+i+'/'+j);
    const explanations=['자료에 적힌 실제 변화는 ','이 관찰의 과학적 해석은 ','이 사례에서 제시된 관찰 조건은 ','자료에 기록되지 않아 직접 알 수 없는 것은 ','이 상황과 연결되는 추가 탐구는 '];
    rows.push([prompts[j][i].replace('%s',title),answers[j],...wrong,detail,explanations[j]+'‘'+answers[j]+'’입니다.']);
   }
  }
  const b=bank(id,'science',[grade],/^(?!)$/,unit+' · '+lesson,rows);
  b.exactUnitName=unit;b.exactLessonName=lesson;b.exactSemester=semester;b.scienceOtherGrades=true;
  b.items[0].scienceMaterial={kind:'table',title:'관찰 비교 · '+lesson,headers:['사례','조사 상황','관찰 결과'],rows:caseRows.map(c=>[c[0],c[1],c[2]]),note:'초등 과학 수업용으로 구성한 예시 관찰 기록. 실제 관측·실험 자료는 현장 조건에 따라 달라질 수 있습니다.'};
  for(let i=0;i<b.items.length;i++){const c=caseRows[Math.floor(i/5)];b.items[i].passageId=id+'-case-'+(Math.floor(i/5)+1);b.items[i].passageTitle=c[0];}
  list.push(b);
 }
 return list;
}
return register;
});